/* Flash cards USMLE: Neurology (822 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["neurology"] = [{"name":"Anatomy & Physiology (Part 1)","cards":[["124jg9k1s","What is the embryologic origin of neurons and glia?","Neurons, astrocytes, oligodendrocytes, ependymal cells: neuroectoderm. Schwann cells: neural crest. Microglia: mesoderm (macrophages).","Origem das células do sistema nervoso."],["1lspxjg26","What are neurons and can they divide?","Signal-transmitting cells; permanent cells that do not divide in adulthood; Nissl bodies in soma and dendrites (not axon).","Células permanentes."],["14n4ictyt","What happens to a neuron after axonal injury?","Wallerian degeneration distal to injury; chromatolysis in the cell body (round, peripheral nucleus, dispersed Nissl).","Degeneração walleriana e cromatólise."],["14aid3nf0","What are astrocytes' functions?","Physical support, repair (reactive gliosis), K+ metabolism, removal of excess neurotransmitter, maintain blood-brain barrier, glycogen fuel reserve; GFAP marker.","Suporte, reparo e barreira."],["13eyfent3","What are microglia?","CNS macrophages; activated in response to injury; form multinucleated giant cells in HIV encephalitis.","Macrófagos do SNC."],["xgp2j4ufv","What are ependymal cells?","Ciliated simple columnar cells lining ventricles and central canal; specialized ependymal cells (choroid plexus) produce CSF.","Revestem os ventrículos."],["10fctcs1j","What do oligodendrocytes do?","Myelinate axons in the CNS; each myelinates multiple axons; fried egg appearance; destroyed in MS, PML, leukodystrophies.","Mielinizam no SNC."],["ev59l7gns","What do Schwann cells do?","Myelinate PNS axons, one Schwann cell per axon segment; promote axonal regeneration; destroyed in Guillain-Barré.","Mielinizam no SNP."],["1tf1iw117","Which tumors derive from Schwann cells?","Schwannomas (vestibular schwannoma at cerebellopontine angle, bilateral in NF2); S-100 positive.","Schwannomas."],["o35usiddl","What is the function of myelin?","Increases conduction velocity (saltatory conduction between nodes of Ranvier) and decreases capacitance.","Acelera a condução."],["x3e3n5rv1","What are the types of sensory receptors and their functions?","Free nerve endings (pain, temperature), Meissner corpuscles (light discriminatory touch), Pacinian corpuscles (vibration, pressure), Merkel discs (pressure, deep static touch), Ruffini corpuscles (stretch).","Receptores sensoriais."],["1qh73ndyx","What is the layer structure of peripheral nerves?","Endoneurium (single fiber), perineurium (fascicle; blood-nerve barrier), epineurium (entire nerve).","Endoneuro, perineuro e epineuro."],["13drden8r","What are the components of the blood-brain barrier?","Tight junctions between nonfenestrated capillary endothelial cells, basement membrane, astrocyte foot processes.","Junções firmes, membrana basal e astrócitos."],["63tzhpeel","What crosses the blood-brain barrier?","Glucose and amino acids by carrier-mediated transport; nonpolar/lipid-soluble substances by diffusion.","Glicose e moléculas lipossolúveis."],["1uxmujh1l","Which brain areas lack a blood-brain barrier?","Circumventricular organs: area postrema (vomiting), OVLT (osmotic sensing), subfornical organ, median eminence, posterior pituitary.","Órgãos circunventriculares."],["y0mj2nnpt","What is vasogenic edema?","BBB disruption (tumors, infection, trauma) causing extracellular fluid accumulation; responds to steroids.","Edema por quebra da barreira."],["1br9qnez0","What is cytotoxic edema?","Cell swelling from ischemia (Na+/K+ pump failure); does not respond to steroids.","Edema celular por isquemia."],["gbo4u5dtj","How is CSF produced and absorbed?","Produced by choroid plexus in ventricles; flows lateral ventricles to 3rd ventricle (foramina of Monro), aqueduct, 4th ventricle, foramina of Luschka and Magendie, subarachnoid space; absorbed by arachnoid granulations into dural venous sinuses.","Produzido no plexo coroide e absorvido nas granulações."],["1x7wv6no8","What is communicating hydrocephalus?","Decreased CSF absorption by arachnoid granulations (subarachnoid hemorrhage, meningitis); increased ICP.","Falha na absorção."],["pg6bw11eq","What is noncommunicating (obstructive) hydrocephalus?","Structural blockage of CSF flow within ventricles (aqueductal stenosis, colloid cyst, tumor).","Bloqueio do fluxo."],["cq4w0x1df","What is normal pressure hydrocephalus?","Idiopathic communicating hydrocephalus in elderly: wet, wobbly, wacky (urinary incontinence, gait apraxia, dementia); ventriculomegaly with normal opening pressure; improves with lumbar puncture.","Incontinência, marcha e demência."],["e0245g7fo","What is hydrocephalus ex vacuo?","Ventricular enlargement from brain atrophy (Alzheimer, HIV, Huntington); normal pressure, not true hydrocephalus.","Ventrículos grandes por atrofia."],["xk8i7i1ys","What is idiopathic intracranial hypertension?","Increased ICP without obvious cause in obese young women: headache, papilledema, diplopia (CN VI), pulsatile tinnitus; associated with vitamin A, tetracyclines, OCPs.","Pseudotumor cerebral em mulher obesa."],["1uo2f1vdn","Treatment of idiopathic intracranial hypertension?","Weight loss, acetazolamide, therapeutic lumbar punctures, optic nerve sheath fenestration, shunting.","Perda de peso e acetazolamida."],["4s9ovm10w","What are the parts of the brainstem?","Midbrain, pons, medulla.","Mesencéfalo, ponte e bulbo."],["va9c2lhib","Which cranial nerves exit from the midbrain?","CN III and IV.","Nervos III e IV."],["61szex124","Which cranial nerves exit from the pons?","CN V, VI, VII, VIII.","V, VI, VII e VIII."],["1uljnsj18","Which cranial nerves exit from the medulla?","CN IX, X, XII (XI from the spinal cord).","IX, X e XII."],["1cyk8ad7b","Which cranial nerve exits from the dorsal brainstem?","CN IV (trochlear).","Nervo troclear."],["1sp896f1p","Which cranial nerve nuclei are medial vs lateral?","Medial: motor (III, IV, VI, XII: factors of 12, except 1 and 2). Lateral: sensory.","Motores mediais; sensitivos laterais."],["i1bdsktfk","What is the function of the hypothalamus?","Thirst and water balance, adenohypophysis control, neurohypophysis release, hunger, autonomic regulation, temperature, sexual urges (TAN HATS).","Sede, fome, temperatura, hormônios."],["dvsqatews","What are the functions of the thalamus?","Major relay for all ascending sensory information except olfaction.","Relé sensitivo exceto olfato."],["fuyz4111a","What does the VPL nucleus of the thalamus relay?","Spinothalamic and dorsal column/medial lemniscus input (pain, temperature, pressure, touch, vibration, proprioception) from the body to primary somatosensory cortex.","Sensibilidade do corpo."],["1tlaalc1l","What does the VPM nucleus of the thalamus relay?","Trigeminal and gustatory input (face sensation and taste).","Face e paladar."],["1xbjkcy19","What does the LGN relay?","Vision from CN II and optic tract to the occipital lobe (calcarine sulcus).","Visão; lateral = luz."],["pyv2ib1mt","What does the MGN relay?","Hearing from superior olive and inferior colliculus to auditory cortex.","Audição; medial = música."],["xbk2411m9","What does the VL nucleus of the thalamus relay?","Motor input from basal ganglia and cerebellum to motor cortex.","Motor."],["1osip6jr6","What does the anterior nucleus of the thalamus do?","Part of the Papez circuit (memory and emotion; limbic system).","Memória e emoção."],["2erhyu6e9","What is the limbic system?","Hippocampus, amygdala, mammillary bodies, anterior thalamic nuclei, cingulate gyrus; feeding, fleeing, fighting, feeling, sex (5 Fs).","Emoções, memória, comportamento."],["1dj7i041k","What are the dopaminergic pathways?","Mesocortical (negative symptoms when decreased), mesolimbic (positive symptoms when increased), nigrostriatal (extrapyramidal motor), tuberoinfundibular (prolactin inhibition).","Vias dopaminérgicas."],["wqoky71ki","What is the function of the cerebellum?","Modulates movement; aids coordination and balance.","Coordenação e equilíbrio."],["g5jyeuy3d","What are the inputs to the cerebellum?","Contralateral cortex via middle cerebellar peduncle; ipsilateral proprioceptive information via inferior cerebellar peduncle from spinal cord.","Córtex contralateral e propriocepção ipsilateral."],["rb2fiqluc","What is the output of the cerebellum?","Purkinje cells (inhibitory) to deep nuclei, which send output via superior cerebellar peduncle to contralateral cortex.","Purkinje para núcleos profundos."],["1xj1jea13","Order of deep cerebellar nuclei from lateral to medial?","Dentate, emboliform, globose, fastigial (Don't Eat Greasy Foods).","Denteado, emboliforme, globoso, fastigial."],["1onu58d1j","What do lateral cerebellar lesions cause?","Ipsilateral limb incoordination, intention tremor, dysmetria; fall toward the side of lesion.","Incoordenação do mesmo lado."],["1j7efj51q","What do medial (vermis) cerebellar lesions cause?","Truncal ataxia (wide-based gait), nystagmus, head tilting; bilateral motor deficits.","Ataxia de tronco."],["e6d1cn12r","What is the function of the basal ganglia?","Voluntary movement and postural adjustments; receive cortical input and provide feedback through the thalamus.","Movimentos voluntários."],["1tfqlzd81","What is the direct (excitatory) pathway of the basal ganglia?","SNc dopamine via D1 receptors stimulates the direct pathway, increasing motion.","Via direta facilita movimento."],["6060jljt7","What is the indirect (inhibitory) pathway of the basal ganglia?","SNc dopamine via D2 receptors inhibits the indirect pathway, increasing motion.","Via indireta inibe movimento."],["1jeg8d536","What structures make up the striatum?","Caudate and putamen.","Caudado e putâmen."],["1qk1x3nkt","What structures make up the lentiform nucleus?","Putamen and globus pallidus.","Putâmen e globo pálido."],["1u33ecqtl","Which basal ganglia lesion causes hemiballismus?","Contralateral subthalamic nucleus lesion (lacunar stroke): sudden wild flailing of one arm.","Núcleo subtalâmico contralateral."],["1v4ja721j","What is the primary motor cortex location?","Precentral gyrus of the frontal lobe.","Giro pré-central."],["fudpld109","What is the primary somatosensory cortex location?","Postcentral gyrus of the parietal lobe.","Giro pós-central."],["mgg862m4h","What does the homunculus show?","Topographic representation of motor and sensory areas; leg and foot medial (ACA), face and arm lateral (MCA).","Pernas mediais, face e braço laterais."],["gekcn4105","Where is Broca area and its function?","Inferior frontal gyrus of the frontal lobe (dominant); motor speech production.","Produção da fala."],["12k9mmv1b","Where is Wernicke area and its function?","Superior temporal gyrus of the temporal lobe (dominant); language comprehension.","Compreensão da linguagem."],["13rj3l5z2","What is the function of the frontal lobe?","Executive function, planning, judgment, personality, motor; lesions cause disinhibition, primitive reflexes.","Funções executivas e personalidade."],["14980tved","What is the function of the parietal lobe?","Somatosensation, spatial orientation; nondominant parietal lesion causes hemispatial neglect.","Sensibilidade e orientação espacial."],["1yd5g0p1h","What is the function of the temporal lobe?","Hearing, language comprehension, memory (hippocampus).","Audição, linguagem e memória."],["2gf54z1v0","What is the function of the occipital lobe?","Vision (primary visual cortex at calcarine sulcus).","Visão."],["4e8vms1tm","What is the frontal eye field?","Area in the frontal lobe controlling voluntary conjugate eye movements; lesion causes eyes to deviate toward the lesion.","Olhos desviam para o lado da lesão."],["rac4011bh","What is the paramedian pontine reticular formation (PPRF)?","Lateral gaze center in the pons; lesion causes eyes to look away from the lesion.","Olhos desviam para o lado oposto."],["9gr0h11bd","What does the amygdala do?","Fear and emotional processing; bilateral lesions cause Klüver-Bucy syndrome.","Medo e emoção."],["5itbnpp66","What is Klüver-Bucy syndrome?","Bilateral amygdala lesion: disinhibited behavior (hyperphagia, hypersexuality, hyperorality); associated with HSV-1 encephalitis.","Hiperoralidade e hipersexualidade."],["hgg7xk18s","What does the hippocampus do?","Memory formation (short-term to long-term); bilateral lesions cause anterograde amnesia; very sensitive to hypoxia.","Formação de memórias."],["ckh1nonec","What do mammillary body lesions cause?","Wernicke-Korsakoff syndrome (thiamine deficiency, alcohol): confusion, ophthalmoplegia, ataxia, memory loss, confabulation.","Wernicke-Korsakoff."],["9qbueh1nf","What does the reticular activating system control?","Arousal and wakefulness; lesions cause coma.","Vigília."],["1rdixuw1c","What is the dural venous sinus drainage?","Cerebral veins to dural sinuses (superior sagittal, inferior sagittal, straight, transverse, sigmoid) to internal jugular vein.","Seios durais para a jugular interna."],["xemj3i12n","What is the confluence of sinuses?","Junction of superior sagittal, straight, and transverse sinuses near the occipital protuberance.","Encontro dos seios."],["ya4b0o1i5","What is cerebral venous sinus thrombosis?","Thrombosis of dural sinuses (hypercoagulable states, OCPs, pregnancy): headache, seizures, focal deficits, increased ICP; MR venography; anticoagulation.","Trombose venosa cerebral."],["18g1aka1s","What does the anterior cerebral artery supply?","Medial surface of frontal and parietal lobes: motor and sensory cortex for lower limb.","Face medial; perna."],["h7qplb1qh","What does the middle cerebral artery supply?","Lateral surface of frontal, parietal, temporal lobes: motor and sensory cortex for upper limb and face; Broca and Wernicke areas (dominant).","Face lateral; braço, face e linguagem."],["n9zi11l90","What does the posterior cerebral artery supply?","Occipital lobe (vision) and inferior temporal lobe.","Lobo occipital."],["4i6818nbe","What are the components of the circle of Willis?","Anterior cerebral arteries, anterior communicating, internal carotid, posterior communicating, posterior cerebral arteries.","Anel arterial na base do cérebro."],["8qs932109","What is the most common site of berry aneurysms?","Junction of anterior communicating and anterior cerebral arteries.","Artéria comunicante anterior."],["o7wl041vq","Which aneurysm compresses CN III causing a blown pupil?","Posterior communicating artery aneurysm (ptosis, down and out eye, dilated pupil).","Comunicante posterior."],["1qxe8p01u","What do lenticulostriate arteries supply?","Striatum and internal capsule; site of lacunar infarcts and hypertensive hemorrhages.","Cápsula interna e núcleos da base."],["1uhaohrcc","What does the anterior spinal artery supply?","Anterior two-thirds of spinal cord and medial medulla.","Dois terços anteriores da medula."],["12hwc366d","What does the posterior inferior cerebellar artery supply?","Lateral medulla and inferior cerebellum.","Bulbo lateral."],["1fzedld1g","What does the anterior inferior cerebellar artery supply?","Lateral pons.","Ponte lateral."],["1dugcw85c","What does the basilar artery supply?","Pons, medulla, lower midbrain; occlusion causes locked-in syndrome.","Tronco cerebral."],["1a2uvce5g","What artery supplies the anterior two-thirds of the tongue?","Lingual artery (external carotid).","Artéria lingual."],["14x4myz1m","What are watershed areas of the brain?","Between ACA/MCA and MCA/PCA territories; damaged in severe hypotension: proximal arm and leg weakness (man in a barrel), visual difficulties.","Áreas de fronteira; homem no barril."],["5wlgiaj8e","Which neurons are most vulnerable to hypoxic injury?","Hippocampus (CA1), neocortex (layers 3, 5, 6), cerebellar Purkinje cells, watershed areas.","Hipocampo e Purkinje."],["1bvymw318","What is the time course of histologic changes after ischemic stroke?","12-24 hours: red neurons. 24-72 hours: necrosis and neutrophils. 3-5 days: macrophages (microglia). 1-2 weeks: reactive gliosis and vascular proliferation. >2 weeks: glial scar (cystic cavity).","Neurônios vermelhos, neutrófilos, macrófagos, gliose."],["84bqrv1im","What imaging is first for suspected stroke?","Noncontrast CT to exclude hemorrhage (ischemic changes may not appear for hours); MRI diffusion-weighted is more sensitive.","Tomografia sem contraste."],["1cpd8rg16","What is a transient ischemic attack?","Brief neurologic dysfunction without acute infarction on MRI; symptoms resolve usually within 1 hour.","Déficit transitório sem infarto."],["142zhsh1f","What is the meninges' structure?","Dura mater (outer, from mesoderm), arachnoid mater, pia mater (inner, from neural crest).","Dura, aracnoide e pia."],["ukgw8x1tv","What is an epidural hematoma?","Rupture of the middle meningeal artery (pterion fracture): lucid interval, then rapid deterioration; biconvex (lentiform) on CT, does not cross suture lines.","Artéria meníngea média; intervalo lúcido."],["1ujnadzrb","What is a subdural hematoma?","Rupture of bridging veins: crescent-shaped, crosses suture lines; acute (trauma) or chronic (elderly, alcoholics, shaken babies).","Veias pontes; crescente."],["19rfkpq1u","What is a subarachnoid hemorrhage?","Bleeding from ruptured aneurysm or AVM: thunderclap headache (worst headache of life), xanthochromic CSF; risk of vasospasm (nimodipine) and rebleeding.","Pior dor de cabeça da vida."],["1muut9die","When does vasospasm occur after SAH and how is it prevented?","3-10 days after; nimodipine.","Entre 3 e 10 dias; nimodipino."],["tuq7ek1ec","What causes intraparenchymal hemorrhage?","Hypertension (Charcot-Bouchard microaneurysms in basal ganglia, thalamus), cerebral amyloid angiopathy (lobar in elderly), AVMs, vasculitis, tumors.","Hipertensão e angiopatia amiloide."],["zhe9sz195","Where do hypertensive hemorrhages occur?","Putamen (basal ganglia) most commonly, thalamus, pons, cerebellum.","Putâmen, tálamo, ponte, cerebelo."],["3hz0t41j4","What is the anatomy of the internal capsule?","Contains corticospinal and corticobulbar fibers; supplied by lenticulostriate arteries; lacunar strokes cause pure motor hemiparesis.","Fibras motoras; AVC lacunar."],["1rbrq5y1g","What are lacunar infarcts?","Small vessel occlusions (lipohyalinosis from hypertension, diabetes) in deep structures causing pure motor, pure sensory, ataxic hemiparesis, or dysarthria-clumsy hand.","Infartos pequenos profundos."],["k6411oqo4","What is the general symptom pattern of an MCA stroke?","Contralateral paralysis and sensory loss of face and upper limb; aphasia if dominant (left); hemineglect if nondominant (right).","Braço e face contralaterais; afasia."],["1nxj3lp1d","What is the general symptom pattern of an ACA stroke?","Contralateral paralysis and sensory loss of the lower limb; urinary incontinence.","Perna contralateral."],["nyqsv61ul","What is the general symptom pattern of a PCA stroke?","Contralateral hemianopia with macular sparing; alexia without agraphia (dominant).","Hemianopsia com preservação macular."],["qy2e1216i","What is the symptom pattern of a PICA stroke (Wallenberg syndrome)?","Lateral medullary syndrome: dysphagia, hoarseness (nucleus ambiguus), decreased gag; vertigo, nystagmus; ipsilateral Horner; ipsilateral face and contralateral body pain/temperature loss; ataxia.","Síndrome bulbar lateral."],["yajr841ib","What is the symptom pattern of an ASA stroke (medial medullary syndrome)?","Contralateral hemiparesis (corticospinal), contralateral proprioception loss (medial lemniscus), ipsilateral tongue deviation (CN XII).","Síndrome bulbar medial."],["hu0fr62oz","What is the symptom pattern of an AICA stroke?","Lateral pontine syndrome: ipsilateral facial paralysis (CN VII), decreased lacrimation and taste, ipsilateral hearing loss, vertigo, ataxia, Horner, face pain/temperature loss.","Síndrome pontina lateral; paralisia facial."],["1bhwl3zkn","What is locked-in syndrome?","Basilar artery occlusion (ventral pons): quadriplegia, loss of horizontal eye movements, preserved consciousness and vertical eye movements (blinking).","Consciente, só move os olhos verticalmente."],["14zcosk1f","What is the dominant hemisphere for most people?","Left hemisphere (language).","Hemisfério esquerdo."],["15ps08zrq","What is hemispatial neglect?","Lesion of nondominant (right) parietal lobe causing agnosia of the contralateral (left) side of the world.","Ignora o lado esquerdo."],["m0d738wys","What is Gerstmann syndrome?","Dominant parietal lobe lesion: agraphia, acalculia, finger agnosia, left-right disorientation.","Agrafia, acalculia, agnosia digital."],["1vg3uydcc","What is Broca (expressive) aphasia?","Nonfluent speech with intact comprehension; impaired repetition; patient is frustrated.","Fala não fluente com compreensão preservada."],["yixswd1ro","What is Wernicke (receptive) aphasia?","Fluent nonsensical speech with impaired comprehension and repetition; patient unaware.","Fala fluente sem sentido."],["1c4lbd11i","What is conduction aphasia?","Damage to arcuate fasciculus: fluent speech, good comprehension, impaired repetition.","Não consegue repetir."],["1gnv95u7g","What is global aphasia?","Broca and Wernicke areas affected: nonfluent speech, impaired comprehension and repetition.","Tudo comprometido."],["s52d0ht3l","What are transcortical aphasias?","Repetition intact: motor (nonfluent, good comprehension), sensory (fluent, poor comprehension), mixed.","Repetição preservada."],["1kfjjsp1s","What is the role of the corpus callosum?","Connects the hemispheres; lesions (split-brain) cause disconnection syndromes.","Conecta os hemisférios."],["14o81h71i","What is the role of the insula?","Taste, interoception, emotion; involved in MCA strokes.","Paladar e interocepção."],["1677f11iv","What is the location of primary auditory cortex?","Superior temporal gyrus (Heschl gyrus).","Giro temporal superior."],["1uadidt1p","What is the location of the primary visual cortex?","Calcarine sulcus of the occipital lobe.","Sulco calcarino."],["91a1nuq91","What are the main neurotransmitters and their sources?","ACh: basal nucleus of Meynert. Dopamine: VTA and SNc. GABA: nucleus accumbens. NE: locus coeruleus. Serotonin: raphe nuclei.","Origem dos neurotransmissores."],["11gw4iguj","What is the role of glutamate in the CNS?","Major excitatory neurotransmitter (NMDA, AMPA receptors); excitotoxicity in stroke.","Principal excitatório."],["mbxgy31wp","What is the role of GABA in the CNS?","Major inhibitory neurotransmitter in the brain (GABA-A chloride channel, GABA-B).","Principal inibitório no cérebro."],["mn1yk0jyf","What is the role of glycine in the spinal cord?","Major inhibitory neurotransmitter in the spinal cord (blocked by strychnine and tetanus toxin).","Inibitório na medula."],["1yp0luc7w","What is the role of substance P?","Pain transmission (released by nociceptive afferents).","Transmissão da dor."],["cvvma81b1","What is the role of endorphins?","Endogenous opioids reducing pain perception.","Opioides endógenos."],["siizlt1b6","What is the gate control theory of pain?","Non-nociceptive input (touch) inhibits pain transmission in the dorsal horn.","Tato inibe a dor na medula."],["145p4n6o4","What is the difference between upper and lower motor neuron signs?","UMN: weakness, spasticity, hyperreflexia, clonus, Babinski positive, no atrophy. LMN: weakness, atrophy, fasciculations, hypotonia, hyporeflexia.","Neurônio motor superior versus inferior."],["12fd7131p","What is the Babinski sign?","Dorsiflexion of the big toe and fanning of toes with plantar stimulation; indicates UMN lesion (normal in infants).","Lesão do neurônio motor superior."],["1aej0531t","What are primitive reflexes and why do they reappear?","Infant reflexes (Moro, rooting, grasp) inhibited by mature frontal lobe; reappear with frontal lobe lesions.","Voltam em lesões frontais."],["159vqk17b","What is the function of the vestibular system?","Senses head rotation (semicircular canals) and linear acceleration and gravity (utricle and saccule).","Rotação e aceleração da cabeça."],["1wqqughyc","What is the vestibulo-ocular reflex?","Keeps eyes fixed during head movement; tested by oculocephalic (doll's eyes) and caloric testing.","Estabiliza o olhar."],["1shyhw8h0","What is the cold caloric test response in a normal awake patient?","Cold water: nystagmus fast phase away from the irrigated ear (COWS: Cold Opposite, Warm Same).","Frio oposto, quente mesmo lado."],["19zubc41f","What does absent caloric response suggest in a comatose patient?","Brainstem dysfunction (brain death evaluation).","Disfunção do tronco."],["1jbbc1yvz","What are the signs of uncal herniation?","Ipsilateral blown pupil (CN III compression), contralateral or ipsilateral (Kernohan notch) hemiparesis, PCA compression (contralateral homonymous hemianopia), Duret hemorrhages.","Pupila dilatada do mesmo lado."],["mhfo221gw","What is subfalcine (cingulate) herniation?","Cingulate gyrus herniates under the falx, compressing ACA (contralateral leg weakness).","Hérnia sob a foice."],["1yafyc31k","What is tonsillar herniation?","Cerebellar tonsils herniate through foramen magnum, compressing the medulla: respiratory arrest, coma, death.","Amígdalas cerebelares comprimem o bulbo."],["11wv6h117","What is central (transtentorial) herniation?","Downward displacement of the brainstem causing Duret hemorrhages (paramedian basilar artery branches).","Hemorragias de Duret."],["11j8xf81o","What is the Cushing triad?","Hypertension, bradycardia, irregular respirations from increased ICP.","Hipertensão, bradicardia e respiração irregular."],["1t0d4mzsb","What is the cerebral perfusion pressure formula?","CPP = MAP - ICP.","Pressão de perfusão = PAM - PIC."],["1rss3jwnc","How do PaCO2 changes affect cerebral blood flow?","Increased PaCO2 causes vasodilation (increases flow and ICP); hyperventilation lowers PaCO2 and ICP temporarily.","CO2 alto dilata vasos."],["p744rrwad","What are the treatments for elevated ICP?","Head elevation, osmotic therapy (mannitol, hypertonic saline), hyperventilation (brief), sedation, CSF drainage, decompressive craniectomy.","Cabeceira elevada, manitol, salina hipertônica."],["1sp8ah9k1","What is the Glasgow Coma Scale?","Eye opening (1-4), verbal response (1-5), motor response (1-6); total 3-15; ≤8 suggests need for intubation.","Escala de coma; ≤8 intubar."],["wraqrozoc","What is decorticate posturing?","Flexion of arms and extension of legs: lesion above the red nucleus (cortex, internal capsule).","Flexão dos braços; lesão alta."],["osikbpfe4","What is decerebrate posturing?","Extension of arms and legs: lesion below the red nucleus (brainstem); worse prognosis.","Extensão; lesão do tronco."],["3ue8u811d","What is brain death?","Irreversible loss of brain function: coma, absent brainstem reflexes, apnea test positive; legally death.","Morte encefálica."],["1v9ul3f1u","What is the persistent vegetative state?","Sleep-wake cycles and arousal without awareness; brainstem function preserved.","Vigília sem consciência."],["1disco73t","What is akinetic mutism?","Lack of movement and speech despite alertness; bilateral medial frontal or anterior cingulate lesions.","Alerta mas sem movimento e fala."],["lj4p391un","What does the corticospinal tract decussate?","At the pyramids in the medulla (caudal medulla).","Nas pirâmides bulbares."],["128tnne9b","Where do the dorsal column fibers decussate?","In the medulla (internal arcuate fibers, forming the medial lemniscus).","No bulbo."],["j799ce101","Where do spinothalamic fibers decussate?","At the spinal cord level via the anterior white commissure (1-2 segments above entry).","Na medula, logo ao entrar."],["14j6p4z1p","What does the spinothalamic tract carry?","Pain, temperature, crude touch.","Dor e temperatura."],["f61c7ihna","What does the dorsal column tract carry?","Fine touch, vibration, proprioception, pressure.","Tato fino, vibração e propriocepção."],["1vxl0nmzs","What is the fasciculus gracilis vs cuneatus?","Gracilis: lower body (medial). Cuneatus: upper body (lateral, above T6).","Grácil inferior; cuneiforme superior."],["q6mtjulv1","What does the lateral corticospinal tract carry?","Voluntary motor commands from cortex to anterior horn LMNs.","Movimento voluntário."],["51f0qu1mn","What is the spinal cord level where it ends in adults?","L1-L2 (conus medullaris).","L1-L2."],["inoitm6z8","Where is a lumbar puncture performed and why?","Between L3-L4 or L4-L5 (at the level of the iliac crests), below the end of the cord to avoid injury.","L3-L4 ou L4-L5."],["7czkz2ven","What layers does a lumbar puncture needle pass through?","Skin, ligaments (supraspinous, interspinous, ligamentum flavum), epidural space, dura, arachnoid, into subarachnoid space.","Camadas da punção lombar."],["zckobt1sv","Where does the subarachnoid space end?","S2.","S2."],["1elwah21d","What is the cauda equina?","Bundle of lumbosacral nerve roots below the conus medullaris.","Raízes lombossacrais."],["1mwl6nu1k","What is the denticulate ligament?","Pial extensions anchoring the spinal cord laterally to the dura.","Fixa a medula lateralmente."],["1vnv4ix41","What is the filum terminale?","Pial extension anchoring the conus to the coccyx.","Fixa o cone ao cóccix."],["1oupjgj1o","What are the cervical and lumbar enlargements?","Spinal cord widening at C5-T1 and L1-S2 due to limb innervation.","Alargamentos para os membros."],["hg192uyrm","What is the anterior horn cell?","Lower motor neuron cell body in ventral spinal gray matter; damaged in polio, ALS, SMA.","Neurônio motor inferior."],["1eu5lm6p8","What is the intermediolateral cell column?","Location of preganglionic sympathetic neurons (T1-L2).","Neurônios simpáticos."],["rk5cnt1jh","What is the dorsal root ganglion?","Contains cell bodies of sensory (pseudounipolar) neurons.","Corpo dos neurônios sensitivos."],["xwqnrk1i9","What is the function of the substantia gelatinosa?","Dorsal horn region processing pain input (Rexed lamina II).","Processa a dor."],["z01wsm1ma","What is the corticobulbar tract?","Motor fibers from cortex to cranial nerve nuclei; mostly bilateral innervation except lower face (CN VII) and CN XII.","Inervação bilateral exceto face inferior."],["amtmxa1vl","Why does a central facial palsy spare the forehead?","Upper face receives bilateral cortical input; lower face only contralateral.","Testa tem inervação bilateral."],["1q3g1y61i","What causes a peripheral (Bell) palsy?","LMN lesion of CN VII: ipsilateral paralysis of the entire face (upper and lower).","Paralisia de toda a hemiface."],["vitzqr1dc","What is the function of oligodendrocyte progenitor cells?","Remyelination after injury (limited).","Remielinização."],["k3shofku2","What determines nerve conduction velocity?","Axon diameter and myelination (larger and myelinated faster).","Diâmetro e mielina."],["il5he2j1b","What are the A-delta and C fibers?","A-delta: thinly myelinated, fast sharp pain and cold. C: unmyelinated, slow burning pain and warmth.","A-delta dor rápida; C dor lenta."],["lbx5971tn","What is the resting membrane potential of neurons?","About -70 mV, mainly determined by K+ permeability.","-70 mV pelo potássio."],["1h3l41wcs","What causes the neuronal action potential upstroke?","Voltage-gated Na+ channel opening.","Abertura de canais de sódio."],["enigoxaax","What is the absolute vs relative refractory period?","Absolute: no AP possible (Na+ channels inactivated). Relative: stronger stimulus needed (K+ channels still open).","Absoluto e relativo."],["1j20qdxv7","How does hyperkalemia affect neuronal excitability?","Depolarizes resting potential, initially increasing excitability then inactivating Na+ channels.","Despolariza e depois inativa."],["13a7m4k11","How do local anesthetics block conduction?","Block voltage-gated Na+ channels from inside; small myelinated fibers blocked first.","Bloqueiam canais de sódio."]]},{"name":"Anatomy & Physiology (Part 2)","cards":[["1ajsm1otm","What is the function of CN I?","Olfactory: smell (only cranial nerve without thalamic relay).","Olfato."],["1dh7r4k1j","What causes anosmia?","Head trauma (cribriform plate fracture), viral infections (COVID-19), Kallmann syndrome, Parkinson and Alzheimer disease, olfactory groove meningioma.","Trauma, viroses, Kallmann."],["18hv40l1i","What is the function of CN II?","Optic: sight; afferent limb of pupillary light reflex.","Visão."],["mr8vczjka","What are the functions of CN III?","Oculomotor: eye movement (SR, IR, MR, IO), pupillary constriction (sphincter pupillae via Edinger-Westphal), accommodation, eyelid opening (levator palpebrae).","Movimento ocular, miose, abertura da pálpebra."],["18hv4bu1i","What is the function of CN IV?","Trochlear: superior oblique (depression and intorsion, especially when adducted).","Oblíquo superior."],["wrigf01ji","What are the functions of CN V?","Trigeminal: facial sensation (V1, V2, V3), mastication muscles (V3), corneal reflex afferent, jaw jerk.","Sensibilidade facial e mastigação."],["18hvle21i","What is the function of CN VI?","Abducens: lateral rectus (abduction).","Reto lateral."],["mqsx6kjjo","What are the functions of CN VII?","Facial: facial movement, taste anterior two-thirds of tongue (chorda tympani), lacrimation, salivation (submandibular and sublingual), stapedius, corneal reflex efferent.","Mímica facial, paladar, lágrimas, saliva."],["149dsdx5r","What are the functions of CN VIII?","Vestibulocochlear: hearing and balance.","Audição e equilíbrio."],["fr8r3v1kk","What are the functions of CN IX?","Glossopharyngeal: taste and sensation posterior one-third of tongue, swallowing (stylopharyngeus), parotid salivation, carotid body and sinus monitoring, gag reflex afferent.","Paladar posterior, parótida, reflexo do vômito."],["wrignm1ji","What are the functions of CN X?","Vagus: taste from epiglottis, swallowing, palate elevation, midline uvula, talking, cough reflex, parasympathetic to thoracoabdominal viscera, aortic arch baroreceptors, gag reflex efferent.","Deglutição, fala, vísceras."],["fr8eu31kk","What are the functions of CN XI?","Accessory: head turning (sternocleidomastoid) and shoulder shrugging (trapezius).","Girar a cabeça e elevar os ombros."],["1brl8jxpf","What is the function of CN XII?","Hypoglossal: tongue movement; lesion causes tongue deviation toward the side of the lesion (LMN).","Língua desvia para o lado da lesão."],["172qpaxol","Mnemonic for cranial nerve sensory, motor, or both?","Some Say Marry Money But My Brother Says Big Brains Matter Most.","Mnemônico S, M ou B."],["f15c2j1jy","What are the cranial nerve reflexes: corneal?","Afferent V1 (nasociliary), efferent VII (orbicularis oculi).","Aferente V1, eferente VII."],["1hgf43q41","What are the cranial nerve reflexes: lacrimation?","Afferent V1, efferent VII.","Aferente V1, eferente VII."],["hy00qx27w","What are the cranial nerve reflexes: jaw jerk?","Afferent V3, efferent V3 (masseter).","V3 nas duas vias."],["b9v4bvsgz","What are the cranial nerve reflexes: pupillary light?","Afferent II, efferent III.","Aferente II, eferente III."],["19b1whu1o","What are the cranial nerve reflexes: gag?","Afferent IX, efferent X.","Aferente IX, eferente X."],["wmpxohtje","Which skull openings transmit V1, V2, V3?","V1: superior orbital fissure. V2: foramen rotundum. V3: foramen ovale (Standing Room Only).","Fissura orbital, redondo, oval."],["1mwl1tu1p","What passes through the superior orbital fissure?","CN III, IV, V1, VI, ophthalmic vein, sympathetic fibers.","III, IV, V1, VI."],["1y88p7g1h","What passes through the internal acoustic meatus?","CN VII and VIII.","VII e VIII."],["b0qn172i4","What passes through the jugular foramen?","CN IX, X, XI, internal jugular vein.","IX, X, XI e jugular."],["20y00j1bm","What passes through the hypoglossal canal?","CN XII.","XII."],["1sstwb813","What passes through the foramen magnum?","Brainstem/spinal cord, spinal root of CN XI, vertebral arteries.","Bulbo, XI e vertebrais."],["1m01rk9a4","What passes through the foramen spinosum?","Middle meningeal artery.","Artéria meníngea média."],["n1euidxpq","What passes through the optic canal?","CN II and ophthalmic artery.","II e artéria oftálmica."],["n1ha32ptb","What passes through the cribriform plate?","CN I.","I."],["zeuwvuywr","What is the cavernous sinus and its contents?","Venous sinus lateral to the pituitary; contains CN III, IV, V1, V2, VI, postganglionic sympathetics, internal carotid artery.","Seio cavernoso."],["1yzerd5dx","What is cavernous sinus syndrome?","Ophthalmoplegia, decreased corneal sensation, Horner syndrome, facial sensation loss (V1, V2); caused by tumor, carotid-cavernous fistula, thrombosis from facial infection.","Oftalmoplegia e perda sensitiva facial."],["d6a6rhufr","Why does CN VI get affected first in cavernous sinus lesions?","It lies free in the sinus next to the internal carotid artery (others are in the lateral wall).","Fica solto dentro do seio."],["1g6kjei1p","What is Bell palsy?","Idiopathic LMN facial nerve palsy (associated with HSV): complete ipsilateral facial paralysis, hyperacusis, loss of taste; treat with steroids.","Paralisia facial periférica; corticoide."],["1d29j1k1c","What are causes of bilateral facial nerve palsy?","Lyme disease, Guillain-Barré, sarcoidosis, HIV.","Lyme, Guillain-Barré, sarcoidose."],["10aiwni16","What is trigeminal neuralgia?","Repetitive unilateral shooting pain in V2/V3 distribution triggered by chewing, talking, touching; treated with carbamazepine.","Dor em choque na face; carbamazepina."],["cumvk519a","What does a CN XII LMN lesion cause?","Tongue deviates toward the lesion side, with atrophy and fasciculations.","Língua desvia para o lado da lesão."],["1gknz1m12","What does a CN X lesion cause?","Uvula deviates away from the lesion side; hoarseness; dysphagia.","Úvula desvia para o lado oposto."],["fnjtr72jm","What does a CN XI lesion cause?","Weakness turning head to the contralateral side (SCM) and shoulder droop on the ipsilateral side (trapezius).","Ombro caído do mesmo lado."],["elgotrq3r","What does a CN V motor lesion cause?","Jaw deviates toward the side of the lesion (unopposed pterygoid).","Mandíbula desvia para a lesão."],["1l99xnt14","What are the effects of a complete spinal cord transection?","Loss of all motor and sensory function below the lesion; spinal shock initially (flaccid, areflexia), then spasticity.","Perda total abaixo da lesão."],["avsvr1os9","What is Brown-Séquard syndrome?","Hemisection of the cord: ipsilateral UMN weakness and loss of proprioception/vibration below lesion; contralateral pain and temperature loss below lesion; ipsilateral loss of all sensation at the level.","Hemissecção medular."],["1mnnyal1y","What is anterior cord syndrome?","Anterior spinal artery occlusion (aortic surgery, dissection): bilateral loss of motor and pain/temperature below the lesion; preserved dorsal columns.","Perde motor e dor; preserva propriocepção."],["1bkcr1i17","What is central cord syndrome?","Hyperextension injury in older adults with cervical spondylosis: weakness of upper more than lower extremities, cape-like sensory loss.","Braços mais fracos que pernas."],["1i7femg1x","What is syringomyelia's classic deficit?","Bilateral loss of pain and temperature in a cape-like distribution (anterior white commissure); later LMN weakness of hands.","Perda térmica e dolorosa em capa."],["10nyay2r3","What is subacute combined degeneration?","B12 deficiency: demyelination of dorsal columns, lateral corticospinal tracts, spinocerebellar tracts: ataxic gait, paresthesias, impaired position and vibration sense, UMN signs.","Falta de B12 lesa cordões posteriores e laterais."],["1e0020mfn","What is tabes dorsalis?","Tertiary syphilis: degeneration of dorsal columns and roots: impaired proprioception, sensory ataxia, Romberg positive, absent DTRs, Argyll Robertson pupils, Charcot joints.","Sífilis terciária nos cordões posteriores."],["f3qexx18n","What is amyotrophic lateral sclerosis?","Combined UMN and LMN degeneration of corticospinal tracts and anterior horns, no sensory or bowel/bladder deficits; SOD1 mutation in some familial cases; riluzole, edaravone.","Neurônio motor superior e inferior; sem perda sensitiva."],["yufk883i2","What is spinal muscular atrophy?","Congenital degeneration of anterior horns (SMN1 deletion): LMN only, floppy baby, tongue fasciculations.","Bebê hipotônico com fasciculações na língua."],["hz4aax15l","What is poliomyelitis's spinal cord damage?","Destruction of anterior horn cells (LMN only): asymmetric flaccid paralysis.","Lesa cornos anteriores."],["1ks6u974h","What is Friedreich ataxia's spinal cord damage?","Degeneration of multiple tracts (dorsal columns, spinocerebellar, lateral corticospinal): ataxia, loss of vibration/proprioception, areflexia, Babinski positive.","Vários tratos."],["1kue03c1e","What is multiple sclerosis's spinal cord pattern?","Asymmetric, scattered white matter lesions in the cervical cord.","Lesões brancas dispersas."],["189rlyfms","What is spinal epidural abscess?","Fever, back pain, neurologic deficits; S. aureus; IV drug users and diabetics; MRI and emergency drainage.","Febre, dor nas costas e déficit."],["c98xyrt1q","What is spinal cord compression from metastasis?","Back pain (worse lying down), then weakness, sensory level, bowel/bladder dysfunction; treat with steroids and radiation/surgery.","Dor nas costas e déficit; corticoide e radioterapia."],["t7wgtw1xa","What does the sympathetic nervous system originate from?","Thoracolumbar spinal cord (T1-L2).","Medula toracolombar."],["r8a8l211j","What does the parasympathetic nervous system originate from?","Craniosacral: CN III, VII, IX, X and S2-S4.","Nervos cranianos e sacral."],["19adee87b","What is the neurotransmitter of all preganglionic autonomic neurons?","Acetylcholine (nicotinic receptors at ganglia).","Acetilcolina."],["1oop2qujg","What is the neurotransmitter of postganglionic sympathetic neurons?","Norepinephrine (except sweat glands: acetylcholine).","Noradrenalina; glândulas sudoríparas usam acetilcolina."],["19ktfqcjj","What is the neurotransmitter of postganglionic parasympathetic neurons?","Acetylcholine (muscarinic receptors).","Acetilcolina."],["1dxil2jeq","What innervates the adrenal medulla?","Preganglionic sympathetic fibers directly (acetylcholine via nicotinic receptors), releasing epinephrine.","Fibras pré-ganglionares diretamente."],["u4eped12d","What is the pathway of sympathetic innervation of the eye?","Hypothalamus to ciliospinal center (C8-T2), to superior cervical ganglion, postganglionic fibers along the carotid to the dilator pupillae, Müller muscle, and sweat glands.","Via de três neurônios até a pupila."],["1yvqsvn14","What is Horner syndrome?","Interruption of sympathetic pathway: ptosis (mild), miosis, anhidrosis (and apparent enophthalmos).","Ptose, miose e anidrose."],["3dz0zt1sq","What lesions cause Horner syndrome?","Pancoast tumor, carotid dissection, Brown-Séquard (above T1), lateral medullary syndrome, cluster headache, cervical rib, syringomyelia.","Tumor de Pancoast, dissecção carotídea."],["1cqd91d1r","Why may anhidrosis be absent in Horner syndrome?","Lesions distal to the carotid bifurcation spare facial sweat fibers (which follow the external carotid).","Lesões distais poupam o suor."],["a4wxvr1sx","What are the effects of parasympathetic stimulation on the eye?","Pupil constriction and accommodation (near vision).","Miose e acomodação."],["1j223fd75","What is the pupillary light reflex pathway?","Light in either eye causes bilateral pupil constriction: retina, CN II, pretectal nuclei, bilateral Edinger-Westphal nuclei, CN III, ciliary ganglion, sphincter pupillae.","Luz em um olho contrai as duas pupilas."],["uz1kst1ao","What is a relative afferent pupillary defect (Marcus Gunn pupil)?","Swinging flashlight test: affected pupil dilates when light moves to it from the normal eye; optic nerve or severe retinal damage (optic neuritis in MS).","Defeito aferente; neurite óptica."],["1hfjrtd1y","What causes a CN III palsy with pupil involvement?","Compressive lesions (posterior communicating artery aneurysm, uncal herniation) affecting superficial parasympathetic fibers: dilated pupil, ptosis, down and out eye.","Compressão; pupila dilatada."],["1dlui3t1h","What causes a CN III palsy sparing the pupil?","Ischemic (diabetes) damage to the central motor fibers: ptosis and down and out eye with normal pupil.","Isquemia diabética; pupila normal."],["1x3gl0ozi","What does a CN IV palsy cause?","Vertical diplopia worse when looking down and in (reading, stairs); head tilt away from the lesion.","Diplopia ao descer escadas."],["2ncl6w1wg","What does a CN VI palsy cause?","Horizontal diplopia; affected eye cannot abduct, deviates medially; increased ICP is a common cause.","Olho não abduz."],["18t2by615","What is internuclear ophthalmoplegia?","Lesion of medial longitudinal fasciculus: ipsilateral eye fails to adduct on lateral gaze with contralateral abducting nystagmus; convergence preserved; MS (bilateral) or stroke.","Lesão do FLM; não aduz."],["1oyqju3l0","What is Parinaud syndrome?","Dorsal midbrain lesion (pinealoma): vertical gaze palsy (especially upward), pupillary light-near dissociation, lid retraction, convergence-retraction nystagmus.","Paralisia do olhar vertical."],["1y7iy2vct","What is the function of the medial longitudinal fasciculus?","Connects CN VI nucleus with contralateral CN III nucleus for conjugate horizontal gaze.","Coordena o olhar horizontal."],["1uytpva2b","What are the effects of a frontal eye field lesion?","Eyes deviate toward the side of the lesion (away from paralyzed side).","Olhos para o lado da lesão."],["dske3h1ib","What are the effects of a seizure in the frontal eye field?","Eyes deviate away from the seizure focus.","Olhos para o lado oposto ao foco."],["wpbidy1hg","What is Argyll Robertson pupil's mechanism?","Lesion of the pretectal area (neurosyphilis): pupils constrict with accommodation but not light.","Lesão pré-tectal."],["1mlo1nwgi","What is Adie tonic pupil?","Damage to ciliary ganglion: dilated pupil poorly reactive to light, slow accommodation; hypersensitivity to dilute pilocarpine; often young women; with absent knee reflexes (Holmes-Adie).","Pupila tônica."],["1hrna901f","What drugs cause miosis?","Opioids, cholinergic agonists, organophosphates, clonidine.","Opioides e colinérgicos."],["xz05ol5z6","What drugs cause mydriasis?","Anticholinergics (atropine), sympathomimetics (cocaine, amphetamines), LSD, withdrawal from opioids.","Anticolinérgicos e simpaticomiméticos."],["1ehfuia1i","What does the autonomic system do to bladder function?","Parasympathetic (S2-S4) contracts detrusor (micturition); sympathetic relaxes detrusor and contracts internal sphincter (storage); somatic pudendal nerve controls external sphincter.","Parassimpático esvazia; simpático armazena."],["kn5fuz1e3","What is a spastic (UMN) bladder?","Lesion above the sacral cord: small, overactive bladder with urgency and reflex incontinence.","Bexiga hiperativa."],["12c6d7gba","What is a flaccid (LMN) bladder?","Sacral cord or nerve lesion (diabetes): large atonic bladder with overflow incontinence.","Bexiga atônica."],["oh73b91yi","What is autonomic dysreflexia?","Spinal cord injury above T6: noxious stimulus below lesion (full bladder) causes massive sympathetic discharge with severe hypertension and reflex bradycardia.","Hipertensão grave em lesão medular alta."],["10tihz015","What is the dermatome of the umbilicus?","T10.","T10."],["1ucwdwh1l","What is the dermatome of the nipple?","T4.","T4."],["wu6hzem73","What is the dermatome of the posterior half of the skull?","C2.","C2."],["l1sfp6125","What is the dermatome of the high turtleneck shirt (neck)?","C3 (diaphragm and gallbladder pain referred to the right shoulder via phrenic nerve C3-C5).","C3."],["1b4bfflhd","What is the dermatome of the inguinal ligament?","L1.","L1."],["6er4235s2","What is the dermatome of the kneecaps?","L4 (down on all fours).","L4."],["1s7rba116","What is the dermatome of the genitalia and anus?","S2, S3, S4.","S2-S4."],["pai00x175","What is the dermatome of the thumb, middle, and little fingers?","C6, C7, C8 respectively.","C6, C7 e C8."],["19wwrdt1d","What is the muscle reflex for S1 and S2?","Achilles reflex (S1, S2: buckle my shoe).","Reflexo aquileu."],["1ngm9vp1y","What is the muscle reflex for L3 and L4?","Patellar reflex (kick the door).","Reflexo patelar."],["15tnhnl18","What is the muscle reflex for C5 and C6?","Biceps and brachioradialis (pick up sticks).","Bicipital."],["18nqyr116","What is the muscle reflex for C7 and C8?","Triceps (lay them straight).","Tricipital."],["1r1tgq920","What is the cremasteric reflex?","L1, L2: stroking the medial thigh elevates the testicle; absent in testicular torsion.","Ausente na torção testicular."],["1f46pmyco","What is the anal wink reflex?","S3, S4.","S3-S4."],["15a8isgsg","What is the role of the vagus nerve in heart rate?","Decreases heart rate (SA node) and AV conduction.","Reduz a frequência cardíaca."],["z5mpez1c1","What are the effects of sympathetic stimulation on bronchi, GI, and bladder?","Bronchodilation (beta2), decreased GI motility, bladder relaxation and sphincter contraction.","Broncodilata, reduz motilidade, retém urina."],["1p0azmy1e","What receptors mediate sweating?","Sympathetic cholinergic muscarinic (M3) receptors.","Receptores muscarínicos."],["13zzeyevl","What is the role of the enteric nervous system?","Intrinsic GI control (myenteric and submucosal plexuses), modulated by autonomic input.","Controle intrínseco do intestino."],["16darq0tw","What are the effects of anticholinergic toxicity?","Hot as a hare, dry as a bone, red as a beet, blind as a bat, mad as a hatter, full as a flask: hyperthermia, dry skin, flushing, mydriasis, delirium, urinary retention.","Quente, seco, vermelho, pupila dilatada, confuso."],["1ie93larf","What are the effects of cholinergic toxicity (organophosphates)?","DUMBELSS: diarrhea, urination, miosis, bronchospasm, bradycardia, emesis, lacrimation, salivation, sweating; muscle fasciculations and paralysis.","Diarreia, miose, broncoespasmo, salivação."],["6uzv0l1fg","Treatment of organophosphate poisoning?","Atropine (muscarinic antagonist) and pralidoxime (regenerates AChE).","Atropina e pralidoxima."],["wx1486rji","What is the pathway of hearing?","Cochlear hair cells, CN VIII, cochlear nuclei, superior olive, lateral lemniscus, inferior colliculus, MGN, auditory cortex.","Via auditiva até o lobo temporal."],["sx2zbx1qg","Where are high vs low frequency sounds detected in the cochlea?","High frequencies at the base (thin, stiff), low frequencies at the apex (wide, flexible).","Agudos na base; graves no ápice."],["czthu8fik","What is noise-induced hearing loss?","Damage to stereocilia from loud noise; high-frequency loss first (4000 Hz dip).","Perda em frequências altas."],["yzgsiiz98","What is presbycusis?","Age-related bilateral sensorineural high-frequency hearing loss.","Perda auditiva do idoso."],["j2g5t4cp6","How does the Weber test help localize hearing loss?","Sound lateralizes to the affected ear in conductive loss, and to the unaffected ear in sensorineural loss.","Condutiva lateraliza para o lado doente."],["26mpvf1uq","What is the Rinne test?","Air conduction > bone conduction is normal or sensorineural; bone > air indicates conductive loss.","Óssea maior que aérea indica perda condutiva."],["j6iqp1lms","What causes conductive hearing loss?","Ear canal obstruction (cerumen), otitis media, tympanic membrane perforation, otosclerosis, cholesteatoma.","Cerume, otite, otosclerose."],["ud6gmrhl8","What is otosclerosis?","Abnormal bone growth fixing the stapes; conductive hearing loss in young adults.","Fixação do estribo."],["o44heb6l6","What is cholesteatoma?","Overgrowth of keratinized squamous epithelium in the middle ear; painless otorrhea and conductive hearing loss; can erode ossicles.","Massa de queratina no ouvido médio."],["1nxtoip1u","What causes sensorineural hearing loss?","Noise, presbycusis, ototoxic drugs (aminoglycosides, loop diuretics, cisplatin), vestibular schwannoma, Ménière disease, congenital CMV.","Ruído, idade, drogas ototóxicas."],["ryk3161el","What is Ménière disease?","Endolymphatic hydrops: episodic vertigo, fluctuating sensorineural hearing loss, tinnitus, aural fullness.","Vertigem, zumbido e perda auditiva."],["cv0g3h5fv","What is benign paroxysmal positional vertigo?","Otoliths in semicircular canals: brief vertigo triggered by head position changes; Dix-Hallpike test; treated with Epley maneuver.","Vertigem com mudança de posição; Epley."],["63pgk41t4","What is vestibular neuritis?","Acute prolonged vertigo with nausea, nystagmus, without hearing loss, after viral infection.","Vertigem aguda sem perda auditiva."],["wdlqiaihz","What is labyrinthitis?","Acute vertigo with hearing loss due to inflammation of the labyrinth.","Vertigem com perda auditiva."],["18bqeyu3u","What distinguishes peripheral from central vertigo?","Peripheral: unidirectional horizontal nystagmus suppressed by fixation, positive head impulse test. Central: vertical or direction-changing nystagmus, other neurologic signs, negative head impulse (HINTS).","Exame HINTS distingue."],["2tu9yrv9h","What is a vestibular schwannoma?","Tumor of CN VIII Schwann cells at the cerebellopontine angle: unilateral sensorineural hearing loss, tinnitus, imbalance; bilateral in NF2.","Tumor do VIII no ângulo pontocerebelar."],["2ns6twbw1","What is the course of the facial nerve?","Exits pons, internal acoustic meatus, facial canal (gives greater petrosal, stapedius, chorda tympani), exits stylomastoid foramen, through parotid to facial muscles.","Trajeto do nervo facial."],["l2ilki1ux","Where can a facial nerve lesion be localized by associated deficits?","Proximal lesions affect lacrimation, hyperacusis (stapedius), and taste; distal lesions (after stylomastoid foramen) only motor.","Sintomas associados localizam a lesão."],["18xhy8412","What is the function of the chorda tympani?","Taste from anterior two-thirds of tongue and parasympathetic to submandibular and sublingual glands.","Paladar e saliva."],["1ndw06zev","What is the function of the greater petrosal nerve?","Parasympathetic to lacrimal gland and nasal mucosa.","Glândula lacrimal."],["1qh0blh1g","What muscles of mastication open vs close the jaw?","Lateral pterygoid opens (lowers); masseter, temporalis, medial pterygoid close (M's munch).","Pterigoide lateral abre; os outros fecham."],["1ccc01w1m","What is the function of the stylopharyngeus?","Elevates the pharynx during swallowing (CN IX).","Eleva a faringe."],["oeb155jqt","What is the gag reflex's afferent and efferent?","Afferent CN IX; efferent CN X.","IX e X."],["11lt0w7zz","What is the carotid sinus reflex?","Afferent CN IX senses stretch; efferent vagus slows the heart.","Seio carotídeo reduz a frequência."],["9sp5ic1yx","What causes dysphagia, hoarseness, and absent gag reflex together?","Lesion of the nucleus ambiguus (CN IX, X) as in lateral medullary syndrome.","Núcleo ambíguo."],["x19poj137","What is the nucleus solitarius's function?","Visceral sensory: taste (VII, IX, X), baroreceptors, chemoreceptors.","Paladar e sensibilidade visceral."],["1k5abu6uv","What is the dorsal motor nucleus of the vagus?","Parasympathetic output to heart, lungs, upper GI.","Saída parassimpática."],["7o5lra1xi","What spinal level is the diaphragm innervated by?","C3-C5 (phrenic nerve).","C3-C5."],["sejgy41ap","What happens with spinal cord injury above C3?","Loss of diaphragm function; ventilator dependence.","Perde a respiração."],["dvknvcpgl","What happens with spinal cord injury at C5-C6?","Retains shoulder and elbow flexion; loses hand function; quadriplegia.","Tetraplegia com ombro preservado."],["ccog6b1a7","What happens with spinal cord injury at T10?","Paraplegia with intact upper extremities.","Paraplegia."],["3vy37jy8z","What is spinal shock?","Initial flaccid paralysis, areflexia, hypotension after acute cord injury; UMN signs appear later.","Fase flácida inicial."],["56ivn18zt","What is neurogenic shock?","Loss of sympathetic tone after cervical or high thoracic cord injury: hypotension with bradycardia and warm skin.","Hipotensão com bradicardia."],["11c0jre18","What is the sensory level?","Level below which sensation is lost, indicating a spinal cord lesion.","Nível sensitivo."],["17sjnk01o","What is the motor pathway of voluntary movement?","UMN in motor cortex, corticospinal tract, decussation in medulla, synapse with LMN in anterior horn, muscle.","Do córtex ao músculo."],["1v8zbj3gp","What is the role of the extrapyramidal system?","Basal ganglia and cerebellum modulate movement; lesions cause tremor, rigidity, chorea.","Modulação do movimento."],["pbq3a1qzk","What is the role of the rubrospinal tract?","Facilitates flexor muscles of upper limbs (decorticate posture).","Facilita flexores dos braços."],["y2ij531gr","What is the role of the vestibulospinal tract?","Facilitates extensor muscles (antigravity, decerebrate posture).","Facilita extensores."],["e323qymr8","What is the role of the spinocerebellar tracts?","Carry unconscious proprioception to the ipsilateral cerebellum.","Propriocepção inconsciente."],["1xy351t1b","What is the role of the reticulospinal tract?","Posture and locomotion.","Postura e locomoção."],["vaeyzrfoz","What is the role of the tectospinal tract?","Reflex head turning in response to visual stimuli.","Virar a cabeça por estímulo visual."],["4sk6p31cm","What is the Romberg test?","Patient stands with feet together and eyes closed; sway indicates loss of proprioception (dorsal columns), not cerebellar dysfunction.","Avalia propriocepção."],["zfjjyw5fe","What does a positive pronator drift indicate?","Upper motor neuron weakness.","Fraqueza de neurônio motor superior."],["ez48saz9t","What is the difference between dysmetria and intention tremor?","Dysmetria: overshooting targets. Intention tremor: tremor increasing as approaching a target; both cerebellar.","Ambos cerebelares."],["cwedn9179","What is dysdiadochokinesia?","Inability to perform rapid alternating movements; cerebellar lesion.","Dificuldade em movimentos alternados."],["1oq71vf12","What is the role of the Edinger-Westphal nucleus?","Parasympathetic preganglionic neurons for pupillary constriction and accommodation.","Constrição pupilar."],["wxw8ap1t3","What is the near reflex triad?","Accommodation (ciliary muscle contraction), convergence (medial rectus), miosis.","Acomodação, convergência e miose."],["bxp5fhymc","What is the course of the optic pathway?","Retina, optic nerve, optic chiasm (nasal fibers cross), optic tract, LGN, optic radiations (Meyer loop temporal, parietal upper), primary visual cortex.","Via óptica."],["1pio4mvoo","What lesion causes a bitemporal hemianopia?","Optic chiasm compression (pituitary adenoma, craniopharyngioma).","Lesão do quiasma."],["1irorb6cz","What lesion causes homonymous hemianopia?","Optic tract lesion (or complete optic radiation/occipital lesion).","Lesão do trato óptico."],["14z97t31k","What lesion causes a pie in the sky (contralateral upper quadrantanopia)?","Meyer loop lesion in the temporal lobe (MCA).","Lesão temporal; alça de Meyer."],["1dq7fdl13","What lesion causes a pie on the floor (contralateral lower quadrantanopia)?","Dorsal optic radiation lesion in the parietal lobe.","Lesão parietal."],["frm9ds8jh","What lesion causes homonymous hemianopia with macular sparing?","PCA infarct of the occipital lobe (macula has dual blood supply).","Infarto da artéria cerebral posterior."],["tgpu59haw","What lesion causes monocular vision loss?","Optic nerve or retinal lesion (central retinal artery occlusion, optic neuritis, amaurosis fugax).","Lesão do nervo óptico ou retina."],["w1e67f1kx","What is amaurosis fugax?","Transient monocular vision loss (curtain) from retinal emboli, often carotid atherosclerosis; warning sign of stroke.","Perda visual transitória; aviso de AVC."],["x2ghz4122","What is a central scotoma?","Loss of central vision (macular degeneration, optic neuritis).","Perda central da visão."],["h2c86d1s9","What is the sensory innervation of the face by V1, V2, V3?","V1: forehead, upper eyelid, nose dorsum. V2: cheek, upper lip, lower eyelid. V3: lower lip, chin, jaw (not angle of jaw, which is C2-C3).","Divisões do trigêmeo na face."],["1rvoh1e19","Which nerve gives sensation to the angle of the mandible?","Great auricular nerve (C2-C3), not trigeminal.","Nervo auricular magno."],["9kwynns3n","What is the sensory innervation of the external ear canal?","CN V3 (auriculotemporal), CN VII, CN X (Arnold nerve: cough reflex when cleaning ear).","V, VII e X; tosse ao limpar o ouvido."],["uwtifo44h","Which nerve supplies the tympanic membrane's inner surface?","CN IX (Jacobson nerve).","IX."],["sl69muel8","What is the innervation of the larynx above and below the vocal cords?","Above: internal laryngeal nerve (sensation). Below: recurrent laryngeal nerve (sensation and motor).","Laríngeo interno acima; recorrente abaixo."],["ae4hl215x","Which muscle opens the vocal cords?","Posterior cricoarytenoid (only abductor, recurrent laryngeal nerve).","Cricoaritenoide posterior."],["in0m6z1jj","Which muscle tenses the vocal cords?","Cricothyroid (external laryngeal nerve).","Cricotireoide."],["v7lgp5v2f","What causes hoarseness after aortic arch surgery or left atrial enlargement?","Left recurrent laryngeal nerve injury.","Lesão do laríngeo recorrente esquerdo."],["13h1xzh1v","What is the course of the right recurrent laryngeal nerve?","Loops under the right subclavian artery.","Contorna a subclávia direita."],["1xk6tky1k","What is the function of the pterygopalatine ganglion?","Parasympathetic to lacrimal gland and nasal mucosa (CN VII via greater petrosal).","Lágrima e mucosa nasal."],["mz6el711f","What is the function of the otic ganglion?","Parasympathetic to the parotid gland (CN IX).","Parótida."],["ayf9ft11n","What is the function of the submandibular ganglion?","Parasympathetic to submandibular and sublingual glands (CN VII via chorda tympani).","Submandibular e sublingual."],["8lm373n2z","What is the function of the ciliary ganglion?","Parasympathetic to sphincter pupillae and ciliary muscle (CN III).","Pupila e acomodação."],["3i0f80ld7","What is the spinal accessory nerve's vulnerability?","Injury in posterior triangle of the neck (lymph node biopsy) causes trapezius weakness.","Lesão no triângulo posterior do pescoço."],["y9rxuj8ky","What is the phrenic nerve's course?","C3-C5, descends on anterior scalene, passes anterior to the lung hilum to the diaphragm.","Passa sobre o escaleno anterior."],["13v45cffx","What does unilateral phrenic nerve injury cause?","Elevated hemidiaphragm on x-ray, dyspnea; paradoxical movement on sniff test.","Hemidiafragma elevado."],["16p31yz32","What is the role of the vagus in swallowing?","Pharyngeal constrictors and palate muscles (except tensor veli palatini and stylopharyngeus).","Constritores da faringe."],["190opn389","What causes hypoglossal nerve injury during carotid endarterectomy?","Proximity of CN XII to the carotid bifurcation; tongue deviates toward the injured side.","Língua desvia para o lado lesado."],["ww0yju1di","What is the most common cause of CN VI palsy in adults?","Microvascular ischemia (diabetes, hypertension) and increased ICP.","Isquemia e hipertensão intracraniana."],["1lqpbtieh","What is the most common cause of CN IV palsy?","Head trauma (and congenital).","Traumatismo craniano."],["1eacplx1n","What is the jaw jerk reflex used for?","Hyperactive in bilateral UMN lesions above the pons (pseudobulbar palsy, ALS).","Exaltado em lesões altas."]]},{"name":"Anatomy & Physiology (Part 3)","cards":[["13ux4q81s","What are the layers of the eye wall?","Sclera and cornea (outer fibrous), uvea (choroid, ciliary body, iris: vascular middle), retina (inner neural).","Esclera/córnea, úvea e retina."],["1bd2vdpai","What produces aqueous humor?","Ciliary body epithelium (nonpigmented).","Corpo ciliar."],["qdhcw31a4","How does aqueous humor drain?","From posterior chamber through the pupil to anterior chamber, then trabecular meshwork and canal of Schlemm (and uveoscleral outflow).","Malha trabecular e canal de Schlemm."],["17tf9itym","What is glaucoma?","Optic neuropathy with optic disc atrophy and cupping (thinning of outer rim) and peripheral visual field loss, usually with increased intraocular pressure.","Lesão do nervo óptico com escavação."],["2fbwelqdg","What is open-angle glaucoma?","Chronic, painless, bilateral peripheral vision loss; obstruction of trabecular meshwork outflow; risk factors: age, African descent, family history.","Perda periférica lenta e indolor."],["706hce1pg","What is acute angle-closure glaucoma?","Lens pushes iris forward, obstructing the angle: very painful red eye, sudden vision loss, halos, headache, nausea, fixed mid-dilated pupil, rock-hard eye; ophthalmologic emergency.","Olho vermelho doloroso; emergência."],["lyr8r319k","Which drugs should be avoided in angle-closure glaucoma?","Mydriatics (anticholinergics, sympathomimetics, epinephrine), which can precipitate an attack.","Midriáticos."],["1hcxatv1u","Treatment of acute angle-closure glaucoma?","Topical beta-blockers, alpha-agonists, pilocarpine, IV acetazolamide or mannitol, then laser peripheral iridotomy.","Reduzir a pressão e iridotomia a laser."],["hva7vu6cz","Which glaucoma drugs decrease aqueous humor production?","Beta-blockers (timolol), alpha-2 agonists (brimonidine), carbonic anhydrase inhibitors (acetazolamide, dorzolamide).","Betabloqueador, brimonidina, acetazolamida."],["1frz6sefx","Which glaucoma drugs increase aqueous outflow?","Prostaglandin analogs (latanoprost, uveoscleral outflow), cholinomimetics (pilocarpine, trabecular outflow), alpha-agonists.","Latanoprosta e pilocarpina."],["835a6dexq","Adverse effect of latanoprost?","Darkening of the iris (brown pigmentation) and eyelash growth.","Escurece a íris."],["1ltu75k5i","What is a cataract?","Painless opacification of the lens causing decreased vision and glare; risk factors: age, smoking, alcohol, sunlight, steroids, diabetes, galactosemia, trauma, infection (congenital rubella).","Opacificação do cristalino."],["15isfrh1s","What is the absence of red reflex in a newborn associated with?","Congenital cataract or retinoblastoma (leukocoria).","Catarata congênita ou retinoblastoma."],["s6cc5k1a9","What is retinoblastoma's presentation?","Leukocoria (white pupillary reflex), strabismus in young children; RB1 mutation.","Reflexo branco na pupila."],["i9lnpl19j","What is myopia?","Eye too long for the refractive power, so light focuses in front of the retina; nearsightedness; corrected with concave (diverging) lens.","Miopia; lente côncava."],["1sonsh718","What is hyperopia?","Eye too short, light focuses behind the retina; farsightedness; corrected with convex (converging) lens.","Hipermetropia; lente convexa."],["lrjegdn6j","What is astigmatism?","Abnormal curvature of the cornea causing different refractive power on different axes.","Curvatura irregular da córnea."],["9l6isysyv","What is presbyopia?","Age-related loss of lens elasticity and accommodation; difficulty with near vision.","Vista cansada da idade."],["1ecm5l4op","What is age-related macular degeneration?","Degeneration of the macula causing central vision loss (scotomas) and distortion (metamorphopsia).","Perda da visão central."],["w4ymdgduf","What is dry vs wet macular degeneration?","Dry (atrophic): drusen, gradual loss; slowed by antioxidant vitamins. Wet (neovascular): rapid loss from choroidal neovascularization; treated with anti-VEGF injections.","Seca com drusas; úmida com neovascularização."],["1dir9nk5v","What is diabetic retinopathy?","Nonproliferative: microaneurysms, hemorrhages, cotton-wool spots, hard exudates, macular edema. Proliferative: neovascularization from chronic hypoxia; treated with anti-VEGF and laser.","Microaneurismas e neovasos."],["ew9sz91h2","What is hypertensive retinopathy?","Arteriovenous nicking, copper/silver wiring, cotton-wool spots, flame hemorrhages; papilledema in malignant hypertension.","Cruzamentos arteriovenosos e exsudatos."],["ey5r3814m","What is central retinal artery occlusion?","Acute painless monocular vision loss; cherry-red spot at the fovea with pale retina; emboli or giant cell arteritis.","Perda súbita indolor; mancha vermelho-cereja."],["1xx0k9l1b","What is central retinal vein occlusion?","Painless vision loss with retinal hemorrhages and venous engorgement (blood and thunder appearance).","Hemorragias em sangue e trovão."],["cnhoumk89","What is retinal detachment?","Separation of neurosensory retina from pigment epithelium: flashes, floaters, curtain over vision; ophthalmologic emergency; risk factors myopia, trauma.","Clarões, moscas volantes e cortina."],["7mc1zs184","What is retinitis pigmentosa?","Inherited retinal degeneration: night blindness, peripheral vision loss (tunnel vision), bone spicule pigmentation.","Cegueira noturna e visão em túnel."],["usrfqi21r","What is papilledema?","Optic disc swelling from increased ICP: blurred disc margins, elevated disc; usually bilateral.","Edema de papila por hipertensão intracraniana."],["1syza81uu","What is optic neuritis?","Inflammation of optic nerve: painful monocular vision loss, pain with eye movement, color desaturation, RAPD; associated with multiple sclerosis.","Dor ao mover o olho; esclerose múltipla."],["9qkb8r1xa","What is uveitis?","Inflammation of uvea (iris, ciliary body, choroid): anterior (iritis: painful red eye, photophobia, hypopyon) or posterior; associated with HLA-B27 diseases, sarcoidosis, Behçet, JIA, IBD.","Olho vermelho doloroso com fotofobia."],["1md5cd215","What is conjunctivitis?","Inflammation of conjunctiva: allergic (itchy, bilateral), bacterial (purulent), viral (watery, preauricular lymphadenopathy, adenovirus).","Conjuntivite alérgica, bacteriana ou viral."],["1ip20uc1o","What is keratitis?","Corneal inflammation (contact lenses: Pseudomonas, Acanthamoeba; HSV dendritic ulcers); painful, photophobia.","Inflamação da córnea."],["nxuojq1h1","What is scleritis?","Severe boring eye pain with deep red sclera; associated with rheumatoid arthritis and vasculitis.","Dor ocular intensa; artrite reumatoide."],["1gd7tzu1h","What is episcleritis?","Benign, mild, sectoral redness of episclera; associated with IBD and RA.","Vermelhidão setorial benigna."],["1t9lglwc7","What is a hordeolum vs chalazion?","Hordeolum (stye): painful acute infection of eyelid gland (S. aureus). Chalazion: painless granulomatous inflammation of meibomian gland.","Terçol dolorido; calázio indolor."],["1fxckyg14","What is orbital cellulitis vs preseptal cellulitis?","Orbital: pain with eye movement, proptosis, ophthalmoplegia (from sinusitis); emergency. Preseptal: eyelid swelling without these signs.","Orbitária tem dor ao mover o olho e proptose."],["194vqfe15","What is strabismus and amblyopia?","Strabismus: misalignment of eyes. Amblyopia: decreased vision in one eye from abnormal visual development (strabismus, refractive error); treated early with patching.","Estrabismo e olho preguiçoso."],["1p9u65f1a","What is the photoreceptor responsible for color and high acuity?","Cones (concentrated in the fovea).","Cones."],["hj1r93ty5","What is the photoreceptor responsible for night and peripheral vision?","Rods (rhodopsin, requires vitamin A).","Bastonetes."],["1ntgpea1p","What is phototransduction?","Light converts 11-cis-retinal to all-trans-retinal, activating transducin and PDE, decreasing cGMP, closing Na+ channels, hyperpolarizing photoreceptors.","Luz hiperpolariza os fotorreceptores."],["1h2h94e1v","Why does vitamin A deficiency cause night blindness?","Insufficient rhodopsin regeneration in rods.","Falta de rodopsina."],["lmehae1tf","What is the blind spot?","Optic disc, where there are no photoreceptors.","Disco óptico."],["1a54doo1l","What is the fovea?","Central pit of the macula with only cones; highest visual acuity.","Maior acuidade visual."],["1q5570z14","What is the role of the ciliary muscle?","Contracts for near vision (accommodation), relaxing zonular fibers so the lens becomes rounder (parasympathetic).","Contrai para ver de perto."],["1896m2n1y","What does the dilator pupillae vs sphincter pupillae do?","Dilator: mydriasis (sympathetic, alpha1). Sphincter: miosis (parasympathetic, M3).","Dilatador simpático; esfíncter parassimpático."],["f852wx15d","What are the extraocular muscles and their nerves?","LR6 SO4, rest 3: lateral rectus (CN VI), superior oblique (CN IV), all others (CN III).","LR6 OS4, o resto III."],["17pt02s1b","What are the actions of the superior and inferior obliques?","Superior oblique: depression and intorsion (best tested looking down and in). Inferior oblique: elevation and extorsion (looking up and in).","Oblíquos."],["3t4t9pxed","How is the superior rectus tested?","Look up and out (abducted).","Olhar para cima e para fora."],["opfinzlx2","What is the role of the levator palpebrae superioris and Müller muscle?","Levator (CN III) raises the eyelid; Müller muscle (sympathetic) provides additional lift; dysfunction causes ptosis.","Elevam a pálpebra."],["rpxdkc10n","What is the function of the lacrimal gland and drainage?","Produces tears (CN VII parasympathetic); drains via puncta, canaliculi, lacrimal sac, nasolacrimal duct into inferior meatus.","Lágrima drena para o nariz."],["1bwhtfyv0","What is the role of the orbicularis oculi?","Closes the eyelid (CN VII); weakness causes inability to close the eye in Bell palsy.","Fecha a pálpebra."],["alwaow13b","What is nystagmus direction naming based on?","Fast phase direction.","Pela fase rápida."],["gzyi0r1o1","What is the role of the superior colliculus?","Visual reflexes and conjugate vertical gaze.","Reflexos visuais."],["8b0hbgaqh","What is the role of the inferior colliculus?","Auditory relay.","Relé auditivo."],["1r0sscc18","What are the types of memory?","Declarative (explicit): episodic and semantic (hippocampus, medial temporal lobe). Nondeclarative (implicit): procedural (basal ganglia, cerebellum).","Memória declarativa e procedural."],["wn7meme0k","What is anterograde vs retrograde amnesia?","Anterograde: cannot form new memories. Retrograde: cannot recall memories before the event.","Não forma novas versus perde antigas."],["1h3flspyb","What causes transient global amnesia?","Sudden temporary anterograde amnesia in middle-aged/older adults, possibly from hippocampal ischemia; resolves within 24 hours.","Amnésia transitória que resolve."],["1lzvxse1y","What is the role of the prefrontal cortex in executive function?","Planning, decision making, working memory, inhibition of inappropriate behavior.","Planejamento e inibição."],["jap5ukrf8","What is the EEG pattern of absence seizures?","3 Hz spike-and-wave discharges.","Ponta-onda de 3 Hz."],["1jsqmuf1n","What is the EEG pattern in Creutzfeldt-Jakob disease?","Periodic sharp wave complexes.","Ondas agudas periódicas."],["lh16nu1iv","What is the EEG pattern in hepatic encephalopathy?","Triphasic waves.","Ondas trifásicas."],["10zb9opob","What is the EEG pattern in HSV encephalitis?","Periodic lateralized epileptiform discharges in the temporal lobe.","Descargas periódicas temporais."],["yavb5mhw4","What is the EEG pattern of infantile spasms (West syndrome)?","Hypsarrhythmia.","Hipsarritmia."],["3mw2bx1gr","What is the role of the area postrema in vomiting?","Chemoreceptor trigger zone sensing toxins in blood (no BBB); D2, 5-HT3, NK1 receptors.","Zona do gatilho do vômito."],["1foyzt094","What receptors are targeted by antiemetics?","5-HT3 (ondansetron), D2 (metoclopramide, prochlorperazine), NK1 (aprepitant), H1 and M1 (motion sickness).","Receptores do vômito."],["bs1949hdq","What is the thermoregulatory center?","Hypothalamus: anterior (cooling) and posterior (heating).","Hipotálamo."],["1x7l3m5ki","How is heat stroke different from fever?","Heat stroke: failure of thermoregulation (core >40°C with CNS dysfunction); fever: hypothalamic set point raised by pyrogens.","Falha da termorregulação versus febre."],["jhjtpk1hi","What is the role of the pineal gland?","Melatonin secretion and circadian rhythm.","Melatonina."],["1dtq2gggq","What is the role of the locus coeruleus?","Main source of norepinephrine; stress, panic, opioid withdrawal.","Noradrenalina; abstinência."],["1i4kzr71m","What is the role of the nucleus accumbens?","Reward and addiction (dopamine).","Recompensa e dependência."],["d5ipc1w12","What is the role of the raphe nuclei?","Serotonin production; mood, sleep, pain.","Serotonina."],["1otn5qq1v","What is the role of the nucleus basalis of Meynert?","Main source of cortical acetylcholine; degenerates in Alzheimer disease.","Acetilcolina; Alzheimer."],["16xz9q710","What is the role of the ventral tegmental area?","Dopamine for mesolimbic and mesocortical pathways (reward, cognition).","Dopamina da recompensa."],["1yoeh3610","What is the role of the substantia nigra pars compacta?","Dopamine for the nigrostriatal pathway (movement); degenerates in Parkinson disease.","Dopamina do movimento; Parkinson."],["zbf0b2kk0","What are NMDA receptors' role in memory?","Long-term potentiation in the hippocampus (learning); blocked by ketamine and memantine.","Potenciação de longo prazo."],["1ajqjg61u","What are the ionotropic vs metabotropic receptors?","Ionotropic: ligand-gated ion channels (nicotinic, GABA-A, NMDA, 5-HT3). Metabotropic: G-protein coupled (muscarinic, GABA-B, dopamine, most serotonin).","Canais iônicos versus acoplados à proteína G."],["t1vmpi1zc","What is the role of the GABA-A receptor?","Ligand-gated chloride channel; potentiated by benzodiazepines (frequency), barbiturates (duration), alcohol.","Canal de cloreto; benzodiazepínicos."],["105txg9pg","What do benzodiazepines vs barbiturates do to the GABA-A channel?","Benzodiazepines increase frequency of opening; barbiturates increase duration (frenzodiazepines, durabarbiturates).","Frequência versus duração."],["wufy6011j","What is the role of the opioid receptors?","Mu (analgesia, euphoria, respiratory depression, constipation), kappa (analgesia, dysphoria), delta (analgesia).","Receptores opioides."],["1gh7l481m","What is the role of the cannabinoid receptors?","CB1 in CNS (psychoactive effects, appetite), CB2 in immune cells.","CB1 no SNC."],["1q5epmp1d","What is the neuromuscular junction transmission process?","AP opens presynaptic voltage-gated Ca2+ channels, ACh release, binds nicotinic receptors, end-plate depolarization, AChE degrades ACh.","Cálcio libera acetilcolina no receptor nicotínico."],["q43xol1w1","What is the role of acetylcholinesterase?","Breaks down acetylcholine in the synaptic cleft; inhibited by pyridostigmine, neostigmine, organophosphates.","Degrada a acetilcolina."],["1w5wc0obb","What is the role of the corticospinal tract's crossing in stroke?","A cortical lesion causes contralateral weakness.","Lesão cortical dá fraqueza do lado oposto."],["1p4iczw1y","What is a crossed (alternating) brainstem syndrome?","Ipsilateral cranial nerve deficit with contralateral body weakness or sensory loss, localizing a brainstem lesion.","Nervo craniano de um lado e corpo do outro."],["nbgh20sgq","What is Weber syndrome?","Medial midbrain lesion (PCA branches): ipsilateral CN III palsy and contralateral hemiparesis.","III nervo e hemiparesia contralateral."],["1hv1wkz12","What is the role of the red nucleus?","Motor coordination of upper limb flexors (rubrospinal).","Coordenação dos flexores."],["1j8wr1g1y","What is the arcuate fasciculus?","White matter tract connecting Wernicke and Broca areas; lesion causes conduction aphasia.","Conecta Wernicke e Broca."],["zdn6fy1pq","What is the Papez circuit?","Hippocampus, fornix, mammillary body, mammillothalamic tract, anterior thalamus, cingulate gyrus, back to hippocampus (memory and emotion).","Circuito da memória."],["v4hlvb1m7","What is the fornix?","Main output tract of the hippocampus to mammillary bodies.","Saída do hipocampo."],["1kvu3131p","What is the role of the cingulate gyrus?","Emotion and pain affect, part of limbic system.","Emoção e afeto da dor."],["1xbvy4jg7","What happens with bilateral hippocampal damage?","Severe anterograde amnesia (inability to form new declarative memories).","Amnésia anterógrada."],["1nij9gv1o","What is the role of Purkinje cells?","Only output of the cerebellar cortex; inhibitory (GABA) to deep nuclei.","Saída inibitória do cerebelo."],["xr963ii6w","What is the role of climbing and mossy fibers?","Inputs to the cerebellum: climbing fibers from inferior olive; mossy fibers from pons, spinal cord, vestibular nuclei.","Entradas do cerebelo."],["1dsrv91n0","What is alcohol's effect on the cerebellum?","Degeneration of the anterior vermis: truncal ataxia, wide-based gait.","Degeneração do verme; ataxia."],["t1lo0j1rr","What is the role of the subthalamic nucleus?","Part of the indirect pathway; deep brain stimulation target in Parkinson disease.","Alvo da estimulação cerebral profunda."],["18wk79dd5","What is the role of the globus pallidus internus?","Main output of the basal ganglia to the thalamus (inhibitory).","Saída dos núcleos da base."],["159rucj10","What is the role of the caudate nucleus?","Cognitive and motor functions; atrophies in Huntington disease.","Atrofia na doença de Huntington."],["tmpdup190","What is the role of the putamen?","Motor function; site of hypertensive hemorrhage.","Motor; hemorragia hipertensiva."],["1qa21go1p","What is the lentiform nucleus?","Putamen and globus pallidus together.","Putâmen e globo pálido."],["p2epnp1ph","What is the claustrum?","Thin gray matter sheet between insula and putamen, involved in consciousness integration.","Lâmina entre ínsula e putâmen."],["uanf41lqa","What is the role of the septal nuclei?","Pleasure and reward; part of limbic system.","Prazer."],["17v76m819","What is the role of the hypothalamic supraoptic and paraventricular nuclei?","Produce ADH and oxytocin.","ADH e ocitocina."],["1s82qetqt","What is the role of the arcuate nucleus?","Produces dopamine (prolactin inhibition), GnRH, GHRH; appetite regulation.","Dopamina, GnRH e apetite."],["1xpdg1kol","What is the function of the mammillary bodies?","Memory (Papez circuit); damaged in Wernicke-Korsakoff.","Memória."],["zr8bl21oz","What is the neural basis of taste?","Taste buds send signals via CN VII, IX, X to nucleus solitarius, then VPM thalamus, then gustatory cortex (insula).","Via do paladar."],["12m8l4a1u","What is the neural basis of smell?","Olfactory receptor neurons through cribriform plate to olfactory bulb, olfactory tract, primary olfactory cortex (no thalamic relay).","Via do olfato sem tálamo."],["lsevea1g1","Which olfactory neurons regenerate?","Olfactory receptor neurons (basal stem cells replace them).","Neurônios olfatórios se renovam."],["w2440010n","What is the brain's main fuel?","Glucose (ketones during prolonged starvation).","Glicose."],["13x3m8811","What is the brain's percentage of resting O2 consumption?","About 20% (receives about 15% of cardiac output).","Cerca de 20%."],["168ew0y1k","What is the role of ependymal cells in hydrocephalus?","Line the ventricles; ependymomas can obstruct CSF flow in the 4th ventricle.","Ependimomas obstruem o líquor."],["1qsgw7a15","What is the normal ICP in adults?","About 5-15 mmHg.","5 a 15 mmHg."],["1cevr29nl","What is the Monro-Kellie doctrine?","Skull volume is fixed; increase in one component (brain, blood, CSF) must be compensated by decrease in another.","Volume fixo dentro do crânio."],["1gmatjp8m","What are signs of increased ICP?","Headache worse lying down and in the morning, vomiting, papilledema, CN VI palsy, altered mental status, Cushing triad.","Cefaleia matinal, vômitos, papiledema."],["vr9z5ppzj","What are the CSF findings in Guillain-Barré syndrome?","Albuminocytologic dissociation: elevated protein with normal cell count.","Proteína alta com células normais."],["u2u9wl157","What are the CSF findings in multiple sclerosis?","Oligoclonal IgG bands, increased IgG index.","Bandas oligoclonais."],["3ww3al1bu","What are the CSF findings in subarachnoid hemorrhage?","Xanthochromia and RBCs that do not clear between tubes.","Xantocromia."],["39mdnb5dc","What is the CSF finding of 14-3-3 protein?","Creutzfeldt-Jakob disease.","Doença de Creutzfeldt-Jakob."],["g3rubkzhn","What is the CSF finding of decreased amyloid-beta and increased tau?","Alzheimer disease.","Alzheimer."],["1w5o3cx4g","What is the visual field defect of a right optic nerve lesion?","Right monocular blindness (anopia).","Cegueira do olho direito."],["1yue597hw","What is the visual field defect of a right optic tract lesion?","Left homonymous hemianopia.","Hemianopsia homônima esquerda."],["jdfein1uj","What is the visual field defect of a right occipital lesion (PCA)?","Left homonymous hemianopia with macular sparing.","Hemianopsia esquerda com mácula preservada."],["1seyaxh3t","What is the visual field defect of central chiasm compression?","Bitemporal hemianopia.","Hemianopsia bitemporal."],["1k98wtabs","What is the visual field defect of a lateral chiasm lesion (internal carotid aneurysm)?","Ipsilateral nasal hemianopia.","Hemianopsia nasal do mesmo lado."],["1ptp8g63t","What is the role of the optic radiations?","Carry visual information from LGN to visual cortex: Meyer loop (temporal, upper field) and dorsal (parietal, lower field).","Radiações ópticas."],["10y6v77ti","What is diplopia when one eye is covered?","If diplopia persists with one eye closed (monocular), cause is ocular (cataract, astigmatism), not neurologic.","Diplopia monocular é ocular."],["19wqzrcbm","What is a Marcus Gunn jaw-winking?","Congenital ptosis that elevates with jaw movement (aberrant CN V-III connection).","Ptose que sobe ao mastigar."],["ia402b1ov","What is the cause of ptosis that worsens during the day with diplopia?","Myasthenia gravis.","Miastenia gravis."],["9ujaf6hta","What is the cause of bilateral ptosis with ophthalmoplegia and ragged red fibers?","Chronic progressive external ophthalmoplegia (mitochondrial).","Oftalmoplegia mitocondrial."],["1i1b2vfwz","What is a pinpoint pupil and coma?","Pontine hemorrhage or opioid overdose.","Hemorragia pontina ou opioide."],["9kp7vk15c","What is a fixed dilated pupil in a comatose patient?","Uncal herniation compressing CN III.","Herniação do úncus."],["af6tlb1mv","What is the cause of ptosis, miosis, and anhidrosis with arm pain in a smoker?","Pancoast tumor compressing the sympathetic chain (Horner) and brachial plexus.","Tumor de Pancoast."],["1luvxkhne","What is the cause of sudden painful Horner syndrome with neck pain?","Carotid artery dissection.","Dissecção da carótida."],["5b1mamot3","What causes light-near dissociation besides syphilis?","Dorsal midbrain lesions (Parinaud), diabetes, Adie tonic pupil.","Parinaud, diabetes, pupila de Adie."],["zgkgc5krc","What is the role of fluorescein staining in eye exam?","Reveals corneal abrasions and ulcers (dendritic ulcer of HSV).","Mostra lesões da córnea."],["11zk7d91r","What is the treatment of corneal abrasion?","Topical antibiotics (antipseudomonal for contact lens wearers); no patching.","Colírio antibiótico."],["snc1mt1vl","What is the treatment of bacterial conjunctivitis?","Topical antibiotics (erythromycin, fluoroquinolones).","Colírio antibiótico."],["4jur4p1e5","What is the treatment of allergic conjunctivitis?","Topical antihistamines and mast cell stabilizers.","Colírio anti-histamínico."],["d8a2651bx","What is the treatment of HSV keratitis?","Topical or oral antivirals; avoid steroids.","Antiviral; evitar corticoide."],["13ftpe51o","What is an ocular finding of Marfan syndrome?","Upward and temporal lens subluxation (ectopia lentis).","Luxação do cristalino para cima."],["14tblq7m3","What is an ocular finding of homocystinuria?","Downward and medial lens subluxation.","Luxação para baixo."],["1a7yyarps","What is an ocular finding of Wilson disease?","Kayser-Fleischer rings (copper in Descemet membrane).","Anéis de Kayser-Fleischer."],["yy0styidd","What is an ocular finding of NF1?","Lisch nodules (iris hamartomas) and optic gliomas.","Nódulos de Lisch."],["5xwmlk1rj","What is an ocular finding of Down syndrome?","Brushfield spots (white iris spots) and upslanting palpebral fissures.","Manchas de Brushfield."],["h16bjxk9h","What is an ocular finding of Tay-Sachs and Niemann-Pick?","Cherry-red spot on macula.","Mancha vermelho-cereja."],["1mpzw5z1w","What is an ocular finding of Graves disease?","Exophthalmos, lid lag, lid retraction, extraocular muscle enlargement.","Exoftalmia."],["9b2qou1rn","What is an ocular finding of sickle cell disease?","Proliferative retinopathy (sea fan neovascularization), especially HbSC.","Retinopatia proliferativa."],["qqtss5xsq","What is an ocular finding of infective endocarditis?","Roth spots (retinal hemorrhages with pale centers).","Manchas de Roth."],["k333sf1l5","What is an ocular finding of CMV in AIDS?","Retinitis with hemorrhages and exudates (pizza pie).","Retinite por CMV."],["cqe7461pf","What is an ocular finding of toxoplasmosis?","Chorioretinitis (headlight in fog).","Coriorretinite."],["7vnbtu1m3","What is an ocular finding of syphilis?","Argyll Robertson pupils, uveitis, interstitial keratitis (congenital).","Pupila de Argyll Robertson."],["14cyako1j","What is an ocular finding of sarcoidosis?","Uveitis (anterior or posterior).","Uveíte."],["22whyj69k","What is an ocular finding of giant cell arteritis?","Anterior ischemic optic neuropathy with sudden vision loss; jaw claudication.","Neuropatia óptica isquêmica."],["1l7ougevf","What is an ocular finding of myasthenia gravis?","Fluctuating ptosis and diplopia.","Ptose e diplopia flutuantes."],["5d3lox115","What is an ocular finding of MS?","Optic neuritis and internuclear ophthalmoplegia.","Neurite óptica e OIN."],["p9qmqd1ic","What is an ocular finding of increased ICP?","Papilledema and CN VI palsy.","Papiledema e VI nervo."],["1b6ody4jv","What is an ocular finding of Horner syndrome?","Miosis, mild ptosis, apparent enophthalmos.","Miose e ptose leve."],["1g3nwa8qp","What is the treatment of central retinal artery occlusion?","Emergency referral; ocular massage and lowering IOP; evaluate for stroke risk and giant cell arteritis.","Emergência; investigar AVC."],["1nukubeyj","What is the treatment of wet macular degeneration?","Intravitreal anti-VEGF (ranibizumab, aflibercept, bevacizumab).","Anti-VEGF intravítreo."],["1dtrjtu10","What is the treatment of proliferative diabetic retinopathy?","Panretinal laser photocoagulation and anti-VEGF.","Laser e anti-VEGF."],["yr43iy1gl","What is the treatment of retinal detachment?","Urgent surgical repair.","Cirurgia urgente."],["ew82ul15l","What is the treatment of cataract?","Surgical lens extraction with intraocular lens implant.","Cirurgia com lente intraocular."],["sns6hakxt","What is the screening for diabetic retinopathy?","Annual dilated eye exam (type 2 at diagnosis; type 1 five years after diagnosis).","Fundo de olho anual."],["1if7bb7kp","What is the role of the tensor tympani and stapedius?","Dampen loud sounds (stapedius CN VII; tensor tympani CN V3); stapedius paralysis causes hyperacusis.","Amortecem sons altos."],["19vprboeh","What is tinnitus's common cause?","Sensorineural hearing loss; pulsatile tinnitus suggests vascular causes.","Perda auditiva neurossensorial."],["oxh4sq1ms","What is the role of the eustachian tube?","Equalizes middle ear pressure; dysfunction predisposes to otitis media in children (short horizontal tubes).","Equaliza pressão do ouvido médio."],["fucr2x1j4","What is the most common cause of acute otitis media in children?","S. pneumoniae (also nontypeable H. influenzae, Moraxella).","Pneumococo."],["1z0zps0kq","What is the treatment of acute otitis media?","Amoxicillin (high dose), or amoxicillin-clavulanate if recent antibiotics.","Amoxicilina."]]},{"name":"Pathology","cards":[["rqtog8ygh","What is the most common cause of dementia?","Alzheimer disease.","Doença de Alzheimer."],["6e8fz41rk","What is the pathology of Alzheimer disease?","Widespread cortical atrophy (hippocampus), extracellular senile plaques (amyloid-beta), intracellular neurofibrillary tangles (hyperphosphorylated tau); decreased ACh.","Placas amiloides e emaranhados de tau."],["6n4j181rj","Which genes are associated with Alzheimer disease?","Early onset: APP (chromosome 21), presenilin 1 and 2. Late onset: ApoE4 increases risk; ApoE2 protective.","APP, presenilinas, ApoE4."],["19akuzv1p","Why does Down syndrome predispose to early Alzheimer disease?","Extra copy of APP gene on chromosome 21.","Cópia extra do gene APP."],["8efaxq1sb","Clinical features of Alzheimer disease?","Insidious progressive memory loss (anterograde first), then language, visuospatial, executive dysfunction; preserved motor until late.","Perda de memória progressiva."],["dip4yr1sv","What is frontotemporal dementia?","Degeneration of frontal and temporal lobes: early personality and behavior changes (disinhibition), aphasia, relatively preserved memory early; Pick bodies (tau).","Mudança de personalidade precoce."],["1t4n8ua1h","What is dementia with Lewy bodies?","Visual hallucinations, fluctuating cognition, parkinsonism, REM sleep behavior disorder; alpha-synuclein Lewy bodies in cortex; sensitivity to antipsychotics.","Alucinações visuais e parkinsonismo."],["1r0pxj3jl","How do you distinguish Lewy body dementia from Parkinson disease dementia?","Lewy body: cognitive symptoms before or within 1 year of parkinsonism. Parkinson dementia: develops years after motor symptoms.","Pela ordem dos sintomas."],["15tq2xok2","What is vascular dementia?","Multiple infarcts or chronic ischemia: stepwise decline, focal neurologic signs; risk factors hypertension, diabetes, smoking.","Piora em degraus."],["1ykb1xwcw","What is Creutzfeldt-Jakob disease's presentation?","Rapidly progressive dementia over months, startle myoclonus, ataxia; periodic sharp waves on EEG; spongiform cortex.","Demência rápida com mioclonia."],["2l08reebf","What is normal pressure hydrocephalus's reversibility?","Potentially reversible with ventriculoperitoneal shunt.","Reversível com derivação."],["5ianx6wk1","What are reversible causes of dementia to rule out?","Hypothyroidism, B12 deficiency, neurosyphilis, normal pressure hydrocephalus, depression (pseudodementia), medications, subdural hematoma.","Hipotireoidismo, B12, sífilis."],["o2jxfx1y8","What is delirium?","Acute fluctuating disturbance of attention and awareness from an underlying medical cause (infection, drugs, metabolic); usually reversible.","Confusão aguda flutuante."],["pfxzd16p4","How do you distinguish delirium from dementia?","Delirium: acute onset, fluctuating, impaired attention and consciousness. Dementia: gradual, stable consciousness.","Delirium agudo; demência gradual."],["1qo1kxj1d","What is multiple sclerosis?","Autoimmune inflammation and demyelination of CNS (brain, spinal cord, optic nerve) with lesions separated in time and space; women 20-30, more common far from equator.","Desmielinização do SNC em mulheres jovens."],["1t70td2ed","Clinical features of multiple sclerosis?","Optic neuritis, internuclear ophthalmoplegia, sensory loss, weakness, spasticity, bladder dysfunction, Lhermitte sign, Uhthoff phenomenon (worse with heat), fatigue.","Neurite óptica, OIN, Lhermitte."],["1igl297go","What is the classic triad of MS (Charcot)?","Scanning speech, intention tremor, nystagmus (SIN).","Fala escandida, tremor de intenção, nistagmo."],["i8q3qsc4x","Imaging findings in multiple sclerosis?","Periventricular white matter plaques (Dawson fingers), juxtacortical, infratentorial, spinal cord lesions on MRI.","Placas periventriculares."],["17tzmzcc3","Treatment of acute MS exacerbation?","High-dose IV glucocorticoids; plasmapheresis if refractory.","Corticoide venoso."],["81n8izp2o","Disease-modifying therapies for MS?","Interferon-beta, glatiramer acetate, natalizumab, fingolimod, dimethyl fumarate, ocrelizumab, teriflunomide, cladribine.","Interferon beta, ocrelizumabe, natalizumabe."],["k1y7w318b","What is neuromyelitis optica?","Autoimmune astrocytopathy (anti-aquaporin-4): severe optic neuritis and longitudinally extensive transverse myelitis.","Anti-aquaporina-4."],["qbo32d1e6","What is Guillain-Barré syndrome?","Acute inflammatory demyelinating polyradiculoneuropathy after infection (Campylobacter, CMV, EBV, Zika, vaccines): ascending symmetric weakness, areflexia, autonomic dysfunction.","Fraqueza ascendente com arreflexia."],["o6g3r61x6","What are the main risks of Guillain-Barré syndrome?","Respiratory failure (monitor vital capacity) and autonomic instability.","Insuficiência respiratória."],["1mhkss8mt","Treatment of Guillain-Barré syndrome?","IVIG or plasmapheresis (not steroids); respiratory support.","Imunoglobulina ou plasmaférese."],["1k19imn12","What is Miller Fisher syndrome?","Guillain-Barré variant: ophthalmoplegia, ataxia, areflexia; anti-GQ1b antibodies.","Oftalmoplegia, ataxia e arreflexia."],["1tppvp21d","What is chronic inflammatory demyelinating polyneuropathy?","Chronic (>8 weeks) progressive or relapsing demyelinating neuropathy; responds to steroids, IVIG.","Forma crônica que responde a corticoide."],["18yufi0h9","What is progressive multifocal leukoencephalopathy?","JC virus demyelination in immunocompromised (AIDS, rituximab, natalizumab): rapidly progressive focal deficits, nonenhancing white matter lesions.","JC vírus em imunossuprimidos."],["1ha7vzttg","What is osmotic demyelination syndrome?","Rapid correction of hyponatremia causes pontine demyelination: acute paralysis, dysarthria, dysphagia, locked-in syndrome.","Correção rápida do sódio."],["y06o2ffhu","What is acute disseminated encephalomyelitis?","Multifocal demyelination after infection or vaccination in children.","Desmielinização pós-infecciosa em crianças."],["1onsdge1a","What are leukodystrophies?","Inherited myelin defects: metachromatic leukodystrophy (arylsulfatase A), Krabbe (galactocerebrosidase), adrenoleukodystrophy (VLCFA).","Doenças hereditárias da mielina."],["1m48xv0m6","What is a seizure?","Abnormal excessive synchronous neuronal activity; epilepsy is recurrent unprovoked seizures.","Atividade neuronal anormal."],["1rgiu0l11","What are focal seizures?","Arise from one area (often medial temporal lobe); with or without impaired awareness; may have aura; may progress to bilateral tonic-clonic.","Crise focal."],["1e0s0gm1w","What are generalized seizures?","Involve both hemispheres: absence, myoclonic, tonic-clonic, tonic, atonic.","Crise generalizada."],["155sq9bs0","What are absence seizures?","Brief (3-20 seconds) staring spells without postictal confusion in children; 3 Hz spike-wave; provoked by hyperventilation; treat with ethosuximide.","Ausências breves; etossuximida."],["1ndker161","What are myoclonic seizures?","Quick repetitive jerks (juvenile myoclonic epilepsy in mornings); valproate.","Abalos rápidos."],["nkk89w11z","What are tonic-clonic seizures?","Alternating stiffening and movement, often with tongue biting, incontinence, postictal confusion.","Convulsão tônico-clônica."],["1kbhmgz9h","What is status epilepticus?","Continuous seizure >5 minutes or recurrent seizures without recovery; treat with benzodiazepines, then fosphenytoin, valproate, or levetiracetam.","Convulsão contínua; benzodiazepínico."],["kw4ka91mq","What are causes of seizures by age?","Children: genetic, infection (febrile), trauma, congenital, metabolic. Adults: tumor, trauma, stroke, infection. Elderly: stroke, tumor, trauma, metabolic, infection.","Causas por faixa etária."],["slmds1wpe","What are febrile seizures?","Seizures in children 6 months-5 years with fever, no CNS infection; simple ones are benign.","Convulsão febril benigna."],["179hh1qgv","What is a Todd paralysis?","Transient focal weakness after a seizure.","Fraqueza transitória pós-crise."],["1nmpnellv","What is a tension-type headache?","Bilateral, steady band-like pain, no photophobia or phonophobia, no aura; lasts 30 minutes to days.","Dor em faixa bilateral."],["13ddri1xf","What is a migraine?","Unilateral, pulsating headache with nausea, photophobia, phonophobia, lasting 4-72 hours; may have aura; due to trigeminal nerve activation and CGRP release.","Dor pulsátil unilateral com náusea."],["wv0nb7s28","Treatment of acute migraine?","NSAIDs, triptans, antiemetics, gepants, lasmiditan.","AINE e triptanos."],["teh6sioo3","Prophylaxis of migraine?","Beta-blockers (propranolol), topiramate, TCAs (amitriptyline), valproate, CGRP antagonists, botulinum toxin.","Propranolol, topiramato, amitriptilina."],["j7ewme1on","What is a cluster headache?","Repetitive brief excruciating unilateral periorbital headaches with lacrimation, rhinorrhea, Horner; mostly men; occur in clusters.","Dor periorbital intensa com lacrimejamento."],["qeyjp6z3b","Treatment of cluster headache?","Acute: 100% oxygen, sumatriptan. Prophylaxis: verapamil.","Oxigênio e verapamil."],["14bj1i5wj","What is giant cell arteritis's headache?","New headache in >50 years with jaw claudication, scalp tenderness, visual symptoms, high ESR.","Cefaleia nova com claudicação da mandíbula."],["1g3dw50ji","What headache red flags require imaging?","Thunderclap onset, new headache after 50, focal deficits, papilledema, worse with Valsalva, immunosuppression, fever with neck stiffness.","Sinais de alerta."],["frmsu3p19","What is medication overuse headache?","Chronic daily headache from frequent analgesic or triptan use.","Cefaleia por uso excessivo de remédios."],["szncpn1au","What is Parkinson disease?","Loss of dopaminergic neurons in the substantia nigra pars compacta; Lewy bodies (alpha-synuclein).","Perda de dopamina na substância negra."],["t9lbu2iuq","Clinical features of Parkinson disease?","TRAP: Tremor (pill-rolling at rest), Rigidity (cogwheel), Akinesia/bradykinesia, Postural instability; shuffling gait, masked facies, micrographia.","Tremor de repouso, rigidez, bradicinesia."],["gwdh9x9yz","What causes drug-induced parkinsonism?","Dopamine antagonists (antipsychotics, metoclopramide); MPTP (synthetic heroin contaminant).","Antipsicóticos e metoclopramida."],["iy7zn81ql","What is Huntington disease?","Autosomal dominant CAG repeat in HTT (chromosome 4): chorea, aggression, depression, dementia; caudate atrophy.","Coreia e demência."],["84ib7r5ru","What is essential tremor?","Action tremor (postural) exacerbated by holding posture, often familial (autosomal dominant), improves with alcohol; treated with propranolol or primidone.","Tremor de ação que melhora com álcool."],["1v37cu5kk","What is intention tremor?","Slow zigzag tremor when pointing toward a target; cerebellar dysfunction.","Tremor ao aproximar do alvo."],["1cjwlhl1u","What is resting tremor?","Uncontrolled movement of distal appendages most noticeable at rest; Parkinson disease.","Tremor de repouso."],["1ejaozcl6","What is chorea?","Sudden jerky purposeless movements; basal ganglia (Huntington, Sydenham chorea).","Movimentos rápidos involuntários."],["smt4rkkyp","What is athetosis?","Slow snake-like writhing movements, especially of fingers; basal ganglia (Huntington).","Movimentos lentos serpenteantes."],["ni3byxyj5","What is dystonia?","Sustained involuntary muscle contractions (writer's cramp, torticollis, blepharospasm).","Contrações musculares sustentadas."],["1qfua49so","What is myoclonus?","Sudden brief muscle contraction (jerks, hiccups); metabolic abnormalities (uremia, liver failure), CJD.","Abalo súbito."],["xpk4vvelm","What is restless legs syndrome?","Urge to move legs worse at rest and at night, relieved by movement; associated with iron deficiency, CKD; treat with dopamine agonists, gabapentinoids, iron.","Pernas inquietas; ferro."],["regcn71ji","What is Tourette syndrome?","Motor and vocal tics starting before 18, lasting >1 year; associated with OCD and ADHD.","Tiques motores e vocais."],["y7xzt81ro","What is the most common primary brain tumor in adults?","Glioblastoma (malignant) and meningioma (benign, most common overall).","Glioblastoma e meningioma."],["kffea41nl","What is glioblastoma?","Grade IV astrocytoma in cerebral hemispheres; can cross corpus callosum (butterfly glioma); pseudopalisading necrosis; GFAP+; poor prognosis.","Tumor maligno em borboleta."],["12wgpyf1s","What is a meningioma?","Benign tumor of arachnoid cells, dural attachment (dural tail), psammoma bodies, whorled pattern; more common in women; associated with NF2.","Tumor benigno com cauda dural."],["1p3327i15","What is a hemangioblastoma?","Cerebellar tumor associated with von Hippel-Lindau; may produce EPO (polycythemia).","Tumor cerebelar no von Hippel-Lindau."],["19udb8w43","What is an oligodendroglioma?","Slow-growing frontal lobe tumor, fried egg cells, chicken-wire capillaries, calcifications; 1p/19q codeletion.","Células em ovo frito e calcificações."],["zbhd5xg7s","What is the most common pituitary tumor?","Prolactinoma (pituitary adenoma).","Prolactinoma."],["1q906vz1b","What is the histologic hallmark of schwannomas?","Antoni A (cellular, Verocay bodies) and Antoni B (loose) areas; S-100 positive.","Áreas Antoni A e B."],["1so93nk1l","What is the most common brain tumor in children (benign)?","Pilocytic astrocytoma: cerebellar cystic tumor, Rosenthal fibers, GFAP+; good prognosis.","Astrocitoma pilocítico."],["cwwvfa174","What is a medulloblastoma?","Malignant cerebellar tumor in children (PNET): drop metastases to spinal cord, Homer-Wright rosettes, can obstruct 4th ventricle (hydrocephalus).","Tumor maligno cerebelar infantil."],["g7yf7symg","What is an ependymoma?","Tumor most commonly in the 4th ventricle in children; perivascular pseudorosettes; hydrocephalus.","Tumor do 4º ventrículo."],["ox2a1sb93","What is a craniopharyngioma's presentation?","Bitemporal hemianopia, hypopituitarism, calcified cystic suprasellar mass in children; motor oil fluid.","Massa suprasselar calcificada."],["10fd039fh","What is a pinealoma's presentation?","Parinaud syndrome, obstructive hydrocephalus, precocious puberty (beta-hCG secretion) in males.","Parinaud e puberdade precoce."],["r06idjswe","What is the most common source of brain metastases?","Lung, breast, melanoma, kidney, colon; often at gray-white junction, multiple.","Pulmão, mama, melanoma."],["10a2pwc1m","What is NF1's neurologic findings?","Neurofibromas, optic gliomas, Lisch nodules, café-au-lait spots, learning disabilities.","Neurofibromas e gliomas ópticos."],["tw65lh1bd","What is tuberous sclerosis's neurologic findings?","Cortical tubers, subependymal nodules, giant cell astrocytoma, seizures (infantile spasms), intellectual disability.","Túberes corticais e convulsões."],["iwhs7sk3d","What is Sturge-Weber syndrome's neurologic findings?","Leptomeningeal angioma, seizures, intellectual disability, port-wine stain (V1), glaucoma; tram-track calcifications.","Angioma leptomeníngeo e mancha vinho."],["19j8n9b81","What is von Hippel-Lindau's neurologic finding?","Cerebellar and retinal hemangioblastomas.","Hemangioblastomas."],["1e5ls8811","What is amyotrophic lateral sclerosis's clinical presentation?","Asymmetric limb weakness with fasciculations, atrophy, spasticity, hyperreflexia, dysarthria, dysphagia; sensation and cognition usually spared; respiratory failure.","Fraqueza com fasciculações e hiper-reflexia."],["14hvs00vc","What is myasthenic crisis?","Respiratory muscle weakness requiring ventilation; treat with IVIG or plasmapheresis.","Fraqueza respiratória na miastenia."],["1qzy67i17","What is cholinergic crisis?","Excess AChE inhibitor: weakness plus cholinergic symptoms (miosis, salivation, bradycardia).","Excesso de anticolinesterásico."],["1vgtmdq1n","What is diabetic neuropathy's typical pattern?","Distal symmetric sensory polyneuropathy (stocking-glove), loss of vibration and ankle reflexes; autonomic neuropathy; mononeuropathies (CN III).","Bota e luva."],["18odm8s1w","What is Charcot-Marie-Tooth disease?","Hereditary motor and sensory neuropathy (PMP22 duplication): foot deformities (pes cavus, hammer toes), lower leg atrophy (inverted champagne bottle), foot drop.","Pés cavos e pernas em garrafa invertida."],["1tocg2kbh","What is complex regional pain syndrome?","Chronic burning pain, swelling, color and temperature changes after injury, out of proportion.","Dor regional crônica após trauma."],["1wxcc991y","What is the presentation of a brain abscess?","Headache, fever, focal deficits, seizures; ring-enhancing lesion; avoid LP if mass effect.","Lesão em anel com febre."],["kw8g0abpz","What is the presentation of bacterial meningitis?","Fever, headache, nuchal rigidity, altered mental status; Kernig and Brudzinski signs; photophobia.","Febre, rigidez de nuca e confusão."],["3od8j1zt3","What should be done before LP in suspected meningitis with focal deficits?","Blood cultures and empiric antibiotics, then head CT, then LP.","Antibiótico antes da tomografia."],["1rkixy6iu","What is the presentation of HSV encephalitis?","Fever, altered mental status, seizures, behavior changes, temporal lobe involvement.","Encefalite temporal."],["8cxnv71i4","What is the presentation of a spinal cord infarction?","Sudden bilateral weakness and loss of pain/temperature with preserved proprioception (anterior spinal artery).","Infarto anterior da medula."],["1n8nw7r5m","What is a concussion?","Mild traumatic brain injury with transient neurologic dysfunction (confusion, amnesia, headache) without structural damage on imaging.","Traumatismo leve sem lesão estrutural."],["boqkv611a","What is diffuse axonal injury?","Shearing injury from acceleration-deceleration: coma with small hemorrhages at gray-white junction; poor prognosis.","Lesão axonal difusa."],["nxtbqzcm6","What is chronic traumatic encephalopathy?","Progressive tauopathy after repetitive head trauma: mood, behavior, cognitive changes.","Encefalopatia por traumas repetidos."],["176j4b4s7","What is a contrecoup injury?","Brain injury at the site opposite the impact.","Lesão do lado oposto ao impacto."],["3zzdqhwu8","What is the presentation of carotid artery stenosis?","TIAs, amaurosis fugax, stroke; carotid bruit.","AITs e amaurose fugaz."],["1t3zda175","When is carotid endarterectomy indicated?","Symptomatic stenosis >70% (or 50-69% in selected), some asymptomatic >70%.","Estenose sintomática acima de 70%."],["ifdagy1ej","What is the treatment window for IV thrombolysis in ischemic stroke?","Within 4.5 hours of symptom onset (if no contraindications); thrombectomy up to 24 hours for large vessel occlusion.","Até 4,5 horas para trombólise."],["i6h6qd1wt","What is secondary prevention after ischemic stroke?","Antiplatelets (aspirin, clopidogrel), statins, blood pressure control, anticoagulation for AF, carotid endarterectomy if indicated.","Antiagregante, estatina, controle pressórico."],["io63s3pgg","What is the most common cause of intracerebral hemorrhage in the elderly in the lobes?","Cerebral amyloid angiopathy.","Angiopatia amiloide."],["1xpwzzgib","What is an arteriovenous malformation?","Abnormal connection between arteries and veins without capillaries: hemorrhage, seizures in young adults.","Conexão anormal arteriovenosa."],["1sq3b81gx","What is a cavernous malformation?","Cluster of dilated capillaries (popcorn on MRI); seizures, hemorrhage.","Malformação em pipoca."],["wjdizq1hi","What is moyamoya disease?","Progressive stenosis of internal carotid arteries with collateral vessels (puff of smoke); strokes in children (Asian descent).","Fumaça na angiografia."],["ys1oab1c4","What is the presentation of syncope vs seizure?","Syncope: brief LOC with rapid recovery, prodrome, pallor. Seizure: longer, postictal confusion, tongue biting, incontinence.","Síncope recupera rápido; crise tem confusão."],["12qc1ns1q","What is narcolepsy?","Excessive daytime sleepiness, cataplexy, hypnagogic/hypnopompic hallucinations, sleep paralysis; low hypocretin (orexin); short REM latency.","Sonolência excessiva e cataplexia."],["1wqbvqt1n","Treatment of narcolepsy?","Modafinil, armodafinil, stimulants, sodium oxybate (cataplexy), pitolisant.","Modafinil e oxibato."],["1fxvelf1a","What is REM sleep behavior disorder?","Acting out dreams due to loss of REM atonia; precursor of synucleinopathies (Parkinson, Lewy body).","Encena os sonhos; precede Parkinson."],["1dlfbjy1i","What is obstructive sleep apnea?","Repeated airway collapse during sleep: snoring, daytime sleepiness, hypertension, obesity; treat with CPAP.","Apneia do sono; CPAP."],["cba5j9cjo","What is the presentation of Wernicke encephalopathy?","Confusion, ophthalmoplegia, ataxia; thiamine deficiency.","Confusão, oftalmoplegia e ataxia."],["1q95d4d1n","What is the presentation of hepatic encephalopathy?","Confusion, asterixis, altered sleep, coma; elevated ammonia.","Confusão e asterixe."],["pxxxii1wc","What is the presentation of uremic encephalopathy?","Confusion, asterixis, myoclonus, seizures in renal failure.","Confusão na uremia."],["1gk2gy71i","What is central pontine myelinolysis's risk group?","Patients with chronic hyponatremia (alcoholics, malnourished) corrected too quickly.","Alcoolistas com hiponatremia crônica."],["cwb5o13w5","What is cerebral palsy?","Nonprogressive motor disorder from perinatal brain injury: spasticity, ataxia, dyskinesia; risk factors prematurity, hypoxia, infection.","Lesão cerebral perinatal não progressiva."],["gy9l2uhgg","What is the most common intracranial hemorrhage in premature infants?","Germinal matrix (intraventricular) hemorrhage.","Hemorragia da matriz germinativa."],["lrka51vcq","What is periventricular leukomalacia?","White matter injury in premature infants causing spastic diplegia.","Lesão da substância branca em prematuros."],["az5096v10","What is the hallmark of a spinal epidural hematoma?","Acute back pain and rapidly progressive paraparesis, often after anticoagulation or epidural procedures.","Dor nas costas e paraparesia rápida."],["wfj5tb195","What is the presentation of cervical myelopathy?","Hand clumsiness, gait disturbance, UMN signs in legs, LMN signs at the level in arms; spondylosis in elderly.","Mielopatia cervical."],["e0t5cm19b","What is radiculopathy vs myelopathy?","Radiculopathy: nerve root compression with dermatomal pain and LMN signs. Myelopathy: spinal cord compression with UMN signs below.","Raiz versus medula."],["ayr45pu98","What is the presentation of polymyositis vs myasthenia gravis?","Polymyositis: proximal weakness with elevated CK, no ocular involvement. Myasthenia: fatigable weakness with ocular involvement, normal CK.","Polimiosite tem CPK alta; miastenia afeta olhos."],["i9337t1rc","What is Duchenne muscular dystrophy's earliest motor sign?","Gowers sign and calf pseudohypertrophy in young boys.","Sinal de Gowers."],["1uvlb25qs","What is myotonic dystrophy's classic finding?","Inability to release grip (myotonia), with cataracts, frontal balding, arrhythmias.","Não solta o aperto de mão."],["47w64b1uf","What is periodic paralysis?","Episodic weakness from ion channel defects, associated with hypo- or hyperkalemia (hypokalemic often with thyrotoxicosis in Asian men).","Fraqueza episódica com alteração do potássio."],["1xfj898f2","What is botulism's clinical presentation in adults?","Symmetric descending flaccid paralysis beginning with cranial nerves (diplopia, dysarthria, dysphagia), dilated pupils, no sensory loss.","Paralisia descendente."],["1slncw1ms","What is tick paralysis?","Ascending flaccid paralysis from a tick neurotoxin; resolves after tick removal.","Paralisia ascendente por carrapato."],["1jmhx6i1s","What is the presentation of neurosyphilis (general paresis)?","Dementia, personality changes, psychosis, Argyll Robertson pupils.","Demência e alteração de personalidade."],["ioul3h1js","What is HIV-associated dementia's imaging?","Diffuse atrophy; microglial nodules with multinucleated giant cells.","Atrofia difusa."],["14s42je1m","What is the most common cause of ring-enhancing lesions in AIDS?","Toxoplasmosis (multiple) vs primary CNS lymphoma (single, EBV PCR in CSF).","Toxoplasmose ou linfoma."],["f1jpxbb0k","What is subacute sclerosing panencephalitis?","Progressive neurodegeneration years after measles infection: myoclonus, dementia; high measles antibody titers.","Complicação tardia do sarampo."],["13qpi5u1f","What is the presentation of Reye syndrome?","Encephalopathy and fatty liver in children after aspirin use during viral illness.","Encefalopatia após aspirina."],["1t4sxcn1g","What is the presentation of lead encephalopathy in children?","Irritability, ataxia, seizures, cerebral edema; pica.","Encefalopatia por chumbo."],["qlm07cjtj","What is the presentation of carbon monoxide poisoning?","Headache, dizziness, confusion, cherry-red skin (late); bilateral globus pallidus lesions.","Cefaleia e lesões do globo pálido."],["1hf1vu814","What is the presentation of methanol poisoning?","Visual disturbances (snowfield vision, blindness), anion gap acidosis; putamen necrosis.","Cegueira e acidose."],["1gn2o4g43","What is the presentation of serotonin syndrome?","Hyperthermia, agitation, tremor, hyperreflexia, clonus, diarrhea after serotonergic drugs; treat with cyproheptadine.","Clônus e hipertermia; ciproeptadina."],["ulp3aeld3","What is the presentation of neuroleptic malignant syndrome?","Fever, rigidity (lead-pipe), altered mental status, autonomic instability, high CK after antipsychotics; treat with dantrolene, bromocriptine.","Febre, rigidez e CPK alta."],["1mm05np12","How do you distinguish NMS from serotonin syndrome?","NMS: slow onset, lead-pipe rigidity, bradyreflexia. Serotonin syndrome: rapid onset, hyperreflexia, clonus, diarrhea.","SNM tem rigidez; serotoninérgica tem clônus."],["m5whbj18c","What is tardive dyskinesia?","Involuntary orofacial movements (lip smacking) after long-term antipsychotic use; treat with valbenazine or deutetrabenazine.","Movimentos orofaciais após antipsicóticos."],["aqo1s8bfu","What is acute dystonia from antipsychotics?","Sudden muscle spasms (torticollis, oculogyric crisis) within hours to days; treat with benztropine or diphenhydramine.","Espasmos agudos; biperideno ou difenidramina."],["17vmb4f52","What is akathisia?","Restlessness and urge to move after antipsychotics; treat with propranolol or benzodiazepines.","Inquietação; propranolol."],["a2dahv1yk","What is the treatment of status epilepticus first line?","IV lorazepam (or IM midazolam, rectal diazepam).","Lorazepam."],["r6yf281fs","What is a psychogenic nonepileptic seizure?","Seizure-like events without EEG changes, often with eyes closed, pelvic thrusting, asynchronous movements.","Crise não epiléptica psicogênica."],["oxwn1h4ot","What is a subarachnoid hemorrhage's complication with hyponatremia?","Cerebral salt wasting or SIADH.","Perda cerebral de sal ou SIADH."],["1xoydh4kx","What is the cause of sudden severe headache with neck stiffness and negative CT?","Still requires LP to look for xanthochromia (SAH).","Fazer punção lombar."],["10vi7qffd","What is the cause of headache worse in the morning with vomiting in a child?","Posterior fossa brain tumor (increased ICP).","Tumor de fossa posterior."],["1g6d46790","What is the treatment of idiopathic intracranial hypertension with vision loss?","Optic nerve sheath fenestration or CSF shunt.","Fenestração da bainha óptica."],["3c5trgbkq","What is the risk of ischemic stroke in patients with patent foramen ovale?","Paradoxical embolism (venous thrombus crossing to arterial side).","Embolia paradoxal."],["1ndh4fv12","What is CADASIL?","Inherited (NOTCH3) small vessel disease: migraines, strokes, dementia in young adults.","Doença genética de pequenos vasos."],["1qon1ik18","What is the presentation of a cerebellar hemorrhage?","Sudden ataxia, vomiting, headache, inability to walk; can compress the brainstem; surgical emergency.","Ataxia súbita e vômitos."],["1sclb6z1h","What is hypoxic-ischemic encephalopathy?","Global brain injury after cardiac arrest: watershed infarcts, laminar necrosis, hippocampal and Purkinje damage.","Lesão cerebral após parada cardíaca."],["4bylxu1u8","What is a fasciculation?","Spontaneous visible twitch of a motor unit; LMN disease (ALS) or benign.","Contração espontânea visível."],["1lkc391eh","What is a contracture vs spasticity?","Contracture: fixed shortening of muscle and tendon. Spasticity: velocity-dependent increased tone (UMN).","Encurtamento fixo versus tônus aumentado."],["1ci8zc71f","What is rigidity in Parkinson disease vs spasticity?","Rigidity: increased tone throughout movement (lead-pipe, cogwheel), extrapyramidal. Spasticity: velocity-dependent, clasp-knife, pyramidal.","Rigidez extrapiramidal; espasticidade piramidal."],["8cj0dj1oz","What is the clasp-knife phenomenon?","Initial resistance then sudden release on passive stretch (UMN spasticity).","Canivete; espasticidade."],["1ond6a8q1","What is asterixis?","Flapping tremor on wrist extension from metabolic encephalopathy (liver failure, uremia, CO2 retention).","Flapping metabólico."],["8paaj07q6","What is the neurologic finding in vitamin E deficiency?","Spinocerebellar ataxia, dorsal column loss, peripheral neuropathy (similar to B12 deficiency without anemia).","Ataxia e perda de propriocepção."],["nbd6xe1yn","What is the neurologic finding in copper deficiency?","Myelopathy similar to B12 deficiency (after bariatric surgery or excess zinc).","Mielopatia semelhante à da B12."],["aj6yu5393","What is the neurologic finding in vitamin B6 deficiency?","Peripheral neuropathy and seizures (isoniazid).","Neuropatia e convulsões."],["1ncw76910","What is the neurologic finding of hypocalcemia?","Tetany, seizures, Chvostek and Trousseau signs.","Tetania e convulsões."],["g0dectamn","What is the neurologic finding of hypoglycemia?","Confusion, seizures, focal deficits mimicking stroke, coma.","Confusão e déficit focal."],["119pkvy1i","What is the presentation of a spinal AVM?","Progressive myelopathy with episodic worsening.","Mielopatia progressiva."],["f0755djpw","What is the hallmark of transverse myelitis?","Acute bilateral motor, sensory, and autonomic dysfunction at a spinal level; post-infectious or MS/NMO.","Lesão inflamatória de um nível medular."],["bduiuuvws","What is the presentation of vertebrobasilar insufficiency?","Dizziness, diplopia, dysarthria, dysphagia, drop attacks, ataxia.","Tontura, diplopia, disartria."],["1g4zdse19","What is the presentation of a thalamic stroke?","Contralateral hemisensory loss; later Dejerine-Roussy thalamic pain syndrome.","Perda sensitiva contralateral e dor talâmica."],["jkwqfa9we","What is the presentation of a pure motor lacunar stroke?","Contralateral face, arm, leg weakness without sensory or cortical signs (posterior limb of internal capsule).","Fraqueza pura sem alteração sensitiva."],["i946o29m2","What is the presentation of a pure sensory lacunar stroke?","Contralateral hemisensory loss from thalamic (VPL/VPM) infarct.","Perda sensitiva pura; tálamo."],["15rxkbw5k","What is the main risk factor for lacunar strokes?","Chronic hypertension (also diabetes).","Hipertensão crônica."],["110jsvr1k","What is the main embolic source in cardioembolic strokes?","Atrial fibrillation (left atrial appendage thrombus); also recent MI, valve disease, endocarditis.","Fibrilação atrial."],["1rt7p4wtd","What imaging test detects acute ischemic stroke earliest?","MRI diffusion-weighted imaging (minutes).","Ressonância com difusão."],["122kl5qac","What is hemorrhagic transformation of ischemic stroke?","Bleeding into infarcted tissue, especially after thrombolysis or large cardioembolic strokes.","Sangramento no infarto."],["1uk8t13b7","What is a common cause of stroke in young patients?","Arterial dissection, cardioembolism (PFO), hypercoagulable states, drugs (cocaine), vasculitis.","Dissecção arterial e cocaína."],["1cfueno1o","What is the role of blood pressure management in acute ischemic stroke?","Permissive hypertension (lower only if >220/120, or >185/110 before thrombolysis).","Hipertensão permissiva."],["r7zbzgh4b","What are the features of an anterior circulation vs posterior circulation stroke?","Anterior: aphasia, neglect, hemiparesis. Posterior: vertigo, ataxia, diplopia, crossed findings, visual field loss.","Anterior: afasia; posterior: vertigem e ataxia."],["5atgg87cd","What is the most common cause of a nontraumatic subarachnoid hemorrhage?","Ruptured saccular (berry) aneurysm.","Aneurisma sacular rompido."],["ems7no5r0","Which conditions are associated with berry aneurysms?","ADPKD, Ehlers-Danlos syndrome, Marfan syndrome, coarctation of the aorta, smoking, hypertension.","Rins policísticos e doenças do colágeno."],["p4e2jg1ye","What is the treatment of a ruptured cerebral aneurysm?","Endovascular coiling or surgical clipping; nimodipine; BP control.","Embolização ou clipagem."],["1gklj3m13","What is a Charcot-Bouchard microaneurysm?","Small aneurysms of lenticulostriate vessels from chronic hypertension causing intraparenchymal hemorrhage.","Microaneurismas da hipertensão."],["n3zcwr1s9","What is the prognosis of pontine hemorrhage?","Poor: coma, pinpoint pupils, quadriplegia.","Coma e pupilas puntiformes."],["1o6uhnq2x","What is the role of seizure prophylaxis after brain trauma?","Short-term antiepileptics (levetiracetam) reduce early post-traumatic seizures.","Levetiracetam por curto prazo."],["3o4vy41lx","What is the treatment of absence seizures besides ethosuximide?","Valproate (and lamotrigine).","Valproato."],["1cyvz2h1h","What is the role of ketogenic diet in epilepsy?","Treatment for refractory pediatric epilepsy and GLUT1 deficiency.","Epilepsia refratária infantil."]]},{"name":"Pharmacology","cards":[["10m7gm17a","Mechanism of phenytoin and fosphenytoin?","Block voltage-gated Na+ channels (use-dependent), inhibiting glutamate release.","Bloqueiam canais de sódio."],["n9gsut15z","Uses of phenytoin?","Focal and tonic-clonic seizures; status epilepticus prophylaxis (fosphenytoin IV).","Crises focais e tônico-clônicas."],["b6dy7ngmj","Adverse effects of phenytoin?","Nystagmus, diplopia, ataxia, gingival hyperplasia, hirsutism, peripheral neuropathy, megaloblastic anemia, teratogenicity (fetal hydantoin syndrome), SJS, DRESS, osteopenia, CYP450 induction, zero-order kinetics.","Hiperplasia gengival, hirsutismo, ataxia."],["p2e517cwf","What kinetics does phenytoin follow at high doses?","Zero-order (saturable) elimination; small dose increases cause large level increases.","Ordem zero em doses altas."],["rsww69xo0","Mechanism and uses of carbamazepine?","Blocks Na+ channels; focal seizures, tonic-clonic seizures, trigeminal neuralgia (first line), bipolar disorder.","Neuralgia do trigêmeo e crises focais."],["1t7ev9zb3","Adverse effects of carbamazepine?","Diplopia, ataxia, agranulocytosis, aplastic anemia, hepatotoxicity, teratogenicity (neural tube defects), SIADH, SJS (HLA-B*15:02), CYP450 induction.","Agranulocitose, SIADH, Stevens-Johnson."],["8nzud1rud","Mechanism and uses of valproate?","Increases Na+ channel inactivation, increases GABA, blocks T-type Ca2+ channels; broad-spectrum: generalized (absence, myoclonic, tonic-clonic) and focal seizures, bipolar disorder, migraine prophylaxis.","Amplo espectro."],["1a7z3sz1l","Adverse effects of valproate?","Hepatotoxicity (measure LFTs), pancreatitis, neural tube defects (spina bifida), tremor, weight gain, hyperammonemia, thrombocytopenia; contraindicated in pregnancy.","Hepatotoxicidade e defeito do tubo neural."],["jdpk41yjc","Mechanism and use of ethosuximide?","Blocks thalamic T-type Ca2+ channels; first-line for absence seizures.","Canais T de cálcio; crise de ausência."],["oe7whl7yg","Adverse effects of ethosuximide?","GI upset, fatigue, headache, urticaria, SJS.","Gastrointestinais e fadiga."],["v0md866fh","Mechanism and uses of lamotrigine?","Blocks voltage-gated Na+ channels and inhibits glutamate release; focal and generalized seizures, bipolar depression.","Bloqueia sódio; bipolar."],["13dk7g3bv","Adverse effect of lamotrigine?","Stevens-Johnson syndrome (titrate slowly, especially with valproate).","Stevens-Johnson; titular devagar."],["3t1wmx13a","Mechanism and uses of levetiracetam?","Binds synaptic vesicle protein SV2A, modulating neurotransmitter release; focal and generalized seizures, status epilepticus.","Liga SV2A; amplo uso."],["359lbx9tm","Adverse effects of levetiracetam?","Neuropsychiatric symptoms (irritability, depression, aggression), fatigue.","Irritabilidade e depressão."],["h6iha7okv","Mechanism and uses of topiramate?","Blocks Na+ channels, increases GABA action, inhibits carbonic anhydrase; focal and tonic-clonic seizures, migraine prophylaxis, weight loss.","Enxaqueca e perda de peso."],["9fdya1mvp","Adverse effects of topiramate?","Cognitive slowing, kidney stones, weight loss, angle-closure glaucoma, metabolic acidosis, paresthesias.","Lentificação cognitiva e cálculos renais."],["1tfc5a61t","Mechanism and uses of gabapentin?","Binds alpha-2-delta subunit of voltage-gated Ca2+ channels; focal seizures, postherpetic neuralgia, diabetic neuropathy, fibromyalgia.","Dor neuropática."],["1jezdlp1x","Mechanism and use of benzodiazepines in seizures?","Increase frequency of GABA-A Cl- channel opening; status epilepticus (lorazepam, diazepam, midazolam), eclampsia (second line).","Estado de mal epiléptico."],["1co6lqk1l","Mechanism and uses of phenobarbital?","Increases duration of GABA-A Cl- channel opening; neonatal seizures first line.","Convulsões neonatais."],["1kvod8a6j","Adverse effects of phenobarbital?","Sedation, respiratory depression, tolerance, CYP450 induction; contraindicated in porphyria.","Sedação e indução do CYP450."],["bdzubf1wo","Mechanism and use of vigabatrin?","Irreversibly inhibits GABA transaminase; infantile spasms (tuberous sclerosis).","Espasmos infantis."],["q1tax916g","Adverse effect of vigabatrin?","Permanent visual field loss.","Perda do campo visual."],["16wlzh61t","Mechanism and use of tiagabine?","Inhibits GABA reuptake; focal seizures.","Inibe recaptação de GABA."],["982t2u1qa","Mechanism and use of lacosamide?","Enhances slow inactivation of Na+ channels; focal seizures; PR prolongation.","Crises focais; prolonga PR."],["u98gynmy9","Which antiepileptic is first line for trigeminal neuralgia?","Carbamazepine.","Carbamazepina."],["1a6k07mlz","Which antiepileptic is first line for absence seizures?","Ethosuximide (valproate if also other generalized seizures).","Etossuximida."],["kioxzh18j","Which antiepileptic is preferred in pregnancy?","Lamotrigine or levetiracetam (with folic acid).","Lamotrigina ou levetiracetam."],["22bcc91hm","Which antiepileptic causes gingival hyperplasia?","Phenytoin.","Fenitoína."],["v35svqku0","Which antiepileptics induce CYP450?","Phenytoin, carbamazepine, phenobarbital (and oxcarbazepine weakly), reducing OCP efficacy.","Fenitoína, carbamazepina, fenobarbital."],["e93kqn101","Which antiepileptic inhibits CYP450?","Valproate.","Valproato."],["1ocxjad17","What is the mechanism of levodopa/carbidopa?","Levodopa crosses the BBB and is converted to dopamine; carbidopa inhibits peripheral DOPA decarboxylase, increasing CNS levodopa and reducing peripheral side effects.","Levodopa vira dopamina; carbidopa protege na periferia."],["1plkrsf17","Adverse effects of levodopa?","Nausea, hypotension, arrhythmias, dyskinesias, on-off phenomenon, hallucinations, psychosis.","Discinesias e fenômeno on-off."],["7a8gp1rp2","Mechanism and use of dopamine agonists (pramipexole, ropinirole)?","Directly stimulate dopamine receptors; Parkinson disease (younger patients), restless legs syndrome.","Agonistas dopaminérgicos."],["ot7akq1gi","Adverse effects of dopamine agonists?","Impulse control disorders (gambling), somnolence, hallucinations, postural hypotension.","Compulsões e sonolência."],["1ylajo31l","Mechanism and use of MAO-B inhibitors (selegiline, rasagiline, safinamide)?","Inhibit dopamine breakdown in the CNS; adjunct in Parkinson disease.","Inibem degradação da dopamina."],["ebol5ykfb","Mechanism and use of COMT inhibitors (entacapone, tolcapone)?","Prevent peripheral levodopa degradation, prolonging its effect; tolcapone is hepatotoxic.","Prolongam a levodopa."],["1omerdc1h","Mechanism and use of amantadine?","Increases dopamine release and NMDA antagonism; Parkinson disease (reduces dyskinesias), influenza A (historically).","Reduz discinesias."],["uxzfxi1po","Adverse effect of amantadine?","Livedo reticularis, ataxia.","Livedo reticular."],["1qyz08bv6","Mechanism and use of benztropine and trihexyphenidyl?","Antimuscarinics improving tremor and rigidity in Parkinson disease (park your Mercedes-Benz); acute dystonia.","Anticolinérgicos para tremor."],["ass6q0bj0","Why avoid anticholinergics in elderly Parkinson patients?","Confusion, urinary retention, constipation.","Confusão e retenção urinária."],["lfx9tr13f","Mechanism and use of tetrabenazine, deutetrabenazine, valbenazine?","VMAT2 inhibitors depleting dopamine; Huntington chorea, tardive dyskinesia.","Inibidores de VMAT2."],["14fcqswho","Which antipsychotic is preferred for psychosis in Parkinson disease?","Pimavanserin (5-HT2A inverse agonist), quetiapine, or clozapine (minimal D2 blockade).","Pimavanserina ou quetiapina."],["caiu4u1gz","Mechanism of AChE inhibitors for Alzheimer disease?","Donepezil, rivastigmine, galantamine increase ACh availability.","Aumentam a acetilcolina."],["5l7icd1sv","Adverse effects of AChE inhibitors?","Nausea, dizziness, insomnia, bradycardia.","Náusea e bradicardia."],["xzcnj0sd6","Mechanism and use of memantine?","NMDA receptor antagonist preventing excitotoxicity; moderate to severe Alzheimer disease.","Antagonista NMDA."],["x9qx616tk","Mechanism of anti-amyloid antibodies (lecanemab, donanemab)?","Monoclonal antibodies clearing amyloid-beta plaques in early Alzheimer disease; risk of ARIA (edema, microhemorrhages).","Removem placas amiloides; risco de ARIA."],["18b1dqc1j","Mechanism and uses of triptans?","5-HT1B/1D agonists: inhibit trigeminal nerve activation and vasoactive peptide release, induce vasoconstriction; acute migraine, cluster headache.","Agonistas 5-HT1B/1D."],["1jj6j2shp","Contraindications to triptans?","Coronary artery disease, Prinzmetal angina, uncontrolled hypertension, stroke history, pregnancy (relative).","Doença coronariana e vasoespasmo."],["11bbqefjb","Mechanism and use of CGRP antagonists?","Monoclonal antibodies (erenumab, fremanezumab) for migraine prophylaxis; gepants (ubrogepant, rimegepant) for acute or preventive treatment.","Anti-CGRP."],["17jf5vw1t","Mechanism and use of lasmiditan?","5-HT1F agonist for acute migraine without vasoconstriction (driving restrictions).","Sem vasoconstrição."],["12bbh4jq3","What are the mechanism of opioid analgesics?","Agonists at mu, delta, kappa receptors: open K+ channels and close Ca2+ channels, decreasing synaptic transmission (inhibit release of ACh, NE, 5-HT, glutamate, substance P).","Agonistas opioides."],["ng69heu6m","Adverse effects of opioids?","Constipation, miosis (tolerance does not develop to these two), respiratory depression, sedation, nausea, addiction, CNS depression with other depressants.","Constipação e miose não desenvolvem tolerância."],["1qzb1xst3","Treatment of opioid overdose?","Naloxone (short acting, may need repeated doses).","Naloxona."],["41rukv19h","Mechanism and uses of naltrexone?","Long-acting opioid antagonist; opioid and alcohol dependence maintenance.","Dependência de álcool e opioides."],["1e7k17d1k","Mechanism and use of buprenorphine?","Partial mu agonist with high affinity; opioid use disorder; can precipitate withdrawal in patients on full agonists.","Agonista parcial."],["1d1omqd16","Mechanism and use of methadone?","Long-acting mu agonist and NMDA antagonist; opioid use disorder maintenance and chronic pain; QT prolongation.","Manutenção; prolonga QT."],["c9z4a3351","Which opioid has serotonergic activity and lowers seizure threshold?","Tramadol.","Tramadol."],["14xxnit17","Which opioid is used for diarrhea?","Loperamide (and diphenoxylate).","Loperamida."],["ub4qsaj7m","Which opioid is used as an antitussive?","Dextromethorphan (also codeine).","Dextrometorfano."],["p9eqf619a","Which opioid metabolite causes seizures in renal failure?","Normeperidine (meperidine metabolite).","Normeperidina."],["16jrx8jz4","Which opioid is a mixed agonist-antagonist?","Butorphanol, nalbuphine, pentazocine (kappa agonist, mu partial or antagonist).","Agonistas-antagonistas mistos."],["8s6tn31pt","What is the mechanism of inhaled anesthetics?","Unclear; increase GABA-A activity, decrease glutamate; myocardial and respiratory depression, decreased cerebral metabolism and increased cerebral blood flow.","Anestésicos inalatórios."],["137lphppn","What is MAC (minimum alveolar concentration)?","Concentration preventing movement in 50% of patients to a surgical incision; inversely related to potency.","Potência inversa à CAM."],["uwnbjrw6r","What determines the speed of induction of inhaled anesthetics?","Blood-gas partition coefficient: low solubility in blood gives rapid induction and recovery (nitrous oxide, desflurane).","Baixa solubilidade no sangue induz rápido."],["13ssuvx1a","What is the potency determinant of inhaled anesthetics?","Lipid solubility (oil-gas partition coefficient): higher solubility, higher potency.","Lipossolubilidade."],["1gjbl0958","Adverse effects of halothane?","Hepatotoxicity (fulminant hepatitis) and malignant hyperthermia.","Hepatite e hipertermia maligna."],["1qbk65n1g","Adverse effect of methoxyflurane?","Nephrotoxicity.","Nefrotoxicidade."],["1hb6ozl1n","Adverse effect of nitrous oxide?","Expansion of trapped gas (pneumothorax), B12 inactivation with prolonged exposure.","Expande gases presos."],["rd5cpj1ic","Mechanism and use of propofol?","Potentiates GABA-A; sedation, induction and maintenance; rapid anesthesia; hypotension.","Indução rápida; hipotensão."],["1rxyj1kpc","Adverse effect of prolonged propofol infusion?","Propofol infusion syndrome: metabolic acidosis, rhabdomyolysis, cardiac failure.","Síndrome da infusão do propofol."],["1fbwyc1fv","Mechanism and use of ketamine?","NMDA receptor antagonist; dissociative anesthesia, analgesia, preserves airway reflexes and BP (sympathomimetic); emergence hallucinations; treatment-resistant depression (esketamine).","Antagonista NMDA; mantém pressão."],["1unm7fy7q","Mechanism and use of etomidate?","GABA-A potentiation; induction with hemodynamic stability; adrenal suppression.","Estável hemodinamicamente; supressão adrenal."],["1pghsi1gl","Mechanism and use of dexmedetomidine?","Central alpha-2 agonist; ICU sedation without respiratory depression; bradycardia and hypotension.","Sedação sem depressão respiratória."],["1ho2ca0bm","Mechanism of local anesthetics?","Block Na+ channels by binding inside the channel in the open/inactivated state; work better in non-acidic tissue.","Bloqueiam canais de sódio."],["fiquietcc","Why are local anesthetics less effective in infected tissue?","Acidic environment keeps the drug ionized, preventing membrane penetration.","Tecido ácido impede a penetração."],["135o6it4a","Order of nerve blockade by local anesthetics?","Small myelinated fibers > small unmyelinated > large myelinated > large unmyelinated; pain lost first, then temperature, touch, pressure.","Dor é bloqueada primeiro."],["1ygig5u2z","What are amide vs ester local anesthetics?","Amides have two i's (lidocaine, bupivacaine, mepivacaine, ropivacaine); esters have one (procaine, tetracaine, benzocaine, chloroprocaine, cocaine).","Amidas têm dois is."],["19nix4y1t","Why is epinephrine added to local anesthetics?","Vasoconstriction decreases bleeding and systemic absorption, prolonging the effect (avoid in end-artery areas historically).","Prolonga o efeito."],["xkx7sr15v","Adverse effects of local anesthetic toxicity?","CNS excitation (seizures), cardiovascular toxicity (bupivacaine), methemoglobinemia (benzocaine), hypertension and arrhythmias (cocaine).","Convulsões e cardiotoxicidade."],["1otnkna2x","Treatment of local anesthetic systemic toxicity?","Lipid emulsion therapy.","Emulsão lipídica."],["8ubt221x5","Mechanism of depolarizing neuromuscular blockade reversal?","Phase I cannot be reversed by AChE inhibitors (worsened); phase II can.","Fase I não reverte com neostigmina."],["o6t67s1ic","Mechanism and use of sugammadex?","Encapsulates rocuronium and vecuronium for rapid reversal.","Encapsula rocurônio."],["1vr9fgz1f","Mechanism and uses of dantrolene?","Ryanodine receptor antagonist preventing Ca2+ release from SR; malignant hyperthermia, neuroleptic malignant syndrome.","Hipertermia maligna."],["1lup44uji","Mechanism and use of baclofen?","GABA-B agonist in spinal cord; spasticity, dystonia, MS.","Espasticidade."],["a8l23i1q7","Mechanism and use of riluzole?","Decreases glutamate excitotoxicity; ALS (modest survival benefit).","Reduz glutamato na ELA."],["ffppepgjj","Mechanism and use of edaravone?","Free radical scavenger; ALS.","Antioxidante na ELA."],["11inpognu","Mechanism and use of nusinersen?","Antisense oligonucleotide modulating SMN2 splicing; spinal muscular atrophy.","Atrofia muscular espinhal."],["vllten528","Mechanism and use of pyridostigmine?","Reversible AChE inhibitor; myasthenia gravis (does not cross BBB).","Miastenia gravis."],["13csmei3p","Mechanism and use of fingolimod?","Sphingosine-1-phosphate receptor modulator sequestering lymphocytes in lymph nodes; MS; bradycardia.","Retém linfócitos nos linfonodos."],["826ljz18o","Mechanism and use of ocrelizumab?","Anti-CD20 B-cell depletion; relapsing and primary progressive MS.","Anti-CD20 na EM."],["1gkgb6v1i","Mechanism and use of natalizumab in MS?","Anti-alpha4 integrin preventing leukocyte entry into the CNS; PML risk (JC virus).","Risco de LEMP."],["zh4ke51vj","Mechanism and use of glatiramer acetate?","Myelin basic protein decoy, modulating T cells; relapsing MS.","Imita proteína da mielina."],["1kg90sx1v","Mechanism and use of dimethyl fumarate?","Activates Nrf2 antioxidant pathway; relapsing MS; flushing, lymphopenia.","Rubor e linfopenia."],["1q0x796tr","Mechanism and use of nimodipine?","Dihydropyridine CCB preventing vasospasm after subarachnoid hemorrhage.","Previne vasoespasmo."],["ya52uqezq","Mechanism and use of mannitol?","Osmotic diuretic reducing intracranial and intraocular pressure; contraindicated in heart failure and anuria.","Reduz pressão intracraniana."],["1or88xw3y","Mechanism and use of alteplase in stroke?","Converts plasminogen to plasmin to lyse clots; within 4.5 hours of ischemic stroke.","Trombolítico."],["7huj37124","Mechanism and use of modafinil?","Promotes wakefulness (dopamine reuptake inhibition); narcolepsy, shift work disorder.","Promove vigília."],["1y2sjn91f","Mechanism and use of sodium oxybate?","GABA-B agonist (GHB); cataplexy and narcolepsy.","Cataplexia."],["16c96fq1w","Mechanism and use of acetazolamide in neurology?","Carbonic anhydrase inhibitor reducing CSF production; idiopathic intracranial hypertension, altitude sickness.","Hipertensão intracraniana idiopática."],["nm1m411cd","Which drugs can cause serotonin syndrome?","SSRIs, SNRIs, MAOIs, TCAs, linezolid, triptans, tramadol, meperidine, dextromethorphan, ondansetron, St. John's wort.","Antidepressivos, linezolida, tramadol."],["kqwyg512b","Which drugs cause seizures?","Bupropion, tramadol, imipenem, isoniazid, local anesthetics, theophylline, meperidine, alcohol or benzodiazepine withdrawal.","Bupropiona, tramadol, isoniazida."],["h5w1561xv","Which drugs cause peripheral neuropathy?","Isoniazid, vincristine, cisplatin, paclitaxel, metronidazole, phenytoin, nitrofurantoin, stavudine.","Isoniazida, vincristina, cisplatina."],["jlyq9heqt","Which drug causes idiopathic intracranial hypertension?","Vitamin A derivatives, tetracyclines, growth hormone, steroid withdrawal.","Vitamina A e tetraciclinas."],["1rgp9r41v","Which drug causes extrapyramidal symptoms besides antipsychotics?","Metoclopramide and prochlorperazine.","Metoclopramida."],["12a1b9nht","Which drug treats essential tremor?","Propranolol or primidone.","Propranolol ou primidona."],["y8wjnb1o0","Which drugs treat restless legs syndrome?","Iron (if ferritin low), gabapentin, pregabalin, dopamine agonists.","Ferro e gabapentina."],["fwvc7f1kn","Which drug treats spasticity via central alpha-2 agonism?","Tizanidine.","Tizanidina."],["yxuve5aoe","Which drug treats chorea in Huntington disease?","Tetrabenazine or deutetrabenazine.","Tetrabenazina."],["1y88z1x1v","Which drug treats Wilson disease neurologic symptoms?","Chelation (trientine, penicillamine) and zinc.","Quelação e zinco."],["jb2duwloh","Which drug treats cluster headache prophylaxis?","Verapamil.","Verapamil."],["5tewb1r1d","Which drug treats acute cluster headache?","High-flow 100% oxygen and subcutaneous sumatriptan.","Oxigênio e sumatriptana."],["1wf3u5g19","Which drug treats postherpetic neuralgia?","Gabapentin, pregabalin, TCAs, lidocaine patch.","Gabapentina."],["1stv7cz1i","Which drug is used for neonatal seizures?","Phenobarbital.","Fenobarbital."],["1dms5a41b","Which drug is used for eclampsia seizures?","Magnesium sulfate.","Sulfato de magnésio."],["1ncsiyb16","Which drug treats infantile spasms?","ACTH or vigabatrin (especially in tuberous sclerosis).","ACTH ou vigabatrina."],["lgbe5w1wu","Which drug treats juvenile myoclonic epilepsy?","Valproate (levetiracetam or lamotrigine in women of childbearing age).","Valproato."],["z19z39gin","Which drug class worsens absence seizures?","Sodium channel blockers like carbamazepine and phenytoin.","Carbamazepina e fenitoína."],["nxy32913y","What should be checked before carbamazepine in Asian patients?","HLA-B*15:02 (risk of SJS/TEN).","HLA-B*15:02."],["qabg6j1sf","Which drug is used to reverse benzodiazepine overdose?","Flumazenil (risk of seizures in chronic users).","Flumazenil."],["2z7406he2","Mechanism of benzodiazepines?","Increase frequency of GABA-A chloride channel opening.","Aumentam a frequência de abertura."],["1645nf11k","Uses of benzodiazepines?","Anxiety, panic, insomnia, alcohol withdrawal, seizures, muscle spasm, night terrors, sleepwalking.","Ansiedade, abstinência alcoólica, convulsões."],["2dq86cwfm","Mechanism of nonbenzodiazepine hypnotics (zolpidem, zaleplon, eszopiclone)?","Act via BZ1 subtype of GABA-A; insomnia; less dependence; reversed by flumazenil.","Drogas Z para insônia."],["dcy5vv1nz","Mechanism and use of suvorexant?","Orexin receptor antagonist; insomnia; contraindicated in narcolepsy.","Antagonista da orexina."],["1wpeqfb6s","Mechanism and use of ramelteon?","Melatonin receptor agonist; insomnia (sleep onset); minimal dependence.","Agonista da melatonina."]]}];
